const TEDED_EV_HISTORY_15QB2VOEOZ0_TRANSLATIONS = [
  `N\u1ebfu b\u1ea1n mua m\u1ed9t chi\u1ebfc \u00f4 t\u00f4 v\u00e0o n\u0103m 1899,`,
  `b\u1ea1n s\u1ebd c\u00f3 ba l\u1ef1a ch\u1ecdn ch\u00ednh.`,
  `B\u1ea1n c\u00f3 th\u1ec3 mua m\u1ed9t chi\u1ebfc \u00f4 t\u00f4 ch\u1ea1y b\u1eb1ng h\u01a1i n\u01b0\u1edbc,`,
  `th\u01b0\u1eddng \u0111\u01b0\u1ee3c \u0111\u1ea9y b\u1eb1ng n\u1ed3i h\u01a1i,`,
  `c\u00f3 th\u1ec3 \u0111i \u0111\u01b0\u1ee3c bao xa t\u00f9y th\u00edch.`,
  `V\u1edbi \u0111i\u1ec1u ki\u1ec7n b\u1ea1n kh\u00f4ng ng\u1ea1i mang th\u00eam n\u01b0\u1edbc d\u1ef1 ph\u00f2ng,`,
  `v\u00e0 c\u0169ng kh\u00f4ng ng\u1ea1i \u0111\u1ee3i 30 ph\u00fat \u0111\u1ec3 \u0111un n\u01b0\u1edbc l\u00e0m n\u00f3ng m\u00e1y.`,
  `B\u1ea1n c\u0169ng c\u00f3 th\u1ec3 mua m\u1ed9t chi\u1ebfc \u00f4 t\u00f4 ch\u1ea1y b\u1eb1ng x\u0103ng,`,
  `tuy nhi\u00ean, \u0111\u1ed9ng c\u01a1 \u0111\u1ed1t trong c\u1ee7a nh\u1eefng m\u1eabu xe n\u00e0y c\u1ea7n ph\u1ea3i kh\u1edfi \u0111\u1ed9ng b\u1eb1ng tay r\u1ea5t nguy hi\u1ec3m,`,
  `v\u1edbi ti\u1ebfng \u1ed3n l\u1edbn v\u00e0 kh\u00ed th\u1ea3i kh\u00f3 ch\u1ecbu tr\u00ean \u0111\u01b0\u1eddng.`,
  `V\u00ec v\u1eady, l\u1ef1a ch\u1ecdn t\u1ed1t nh\u1ea5t c\u1ee7a b\u1ea1n c\u00f3 l\u1ebd l\u00e0 l\u1ef1a ch\u1ecdn th\u1ee9 ba,`,
  `m\u1ed9t chi\u1ebfc \u00f4 t\u00f4 \u0111i\u1ec7n ch\u1ea1y b\u1eb1ng pin.`,
  `Nh\u1eefng chi\u1ebfc xe n\u00e0y kh\u1edfi \u0111\u1ed9ng nhanh,`,
  `th\u00e2n thi\u1ec7n v\u1edbi m\u00f4i tr\u01b0\u1eddng v\u00e0 ch\u1ea1y \u00eam \u00e1i.`,
  `N\u1ebfu b\u1ea1n s\u1ed1ng \u1edf n\u01a1i c\u00f3 \u0111i\u1ec7n,`,
  `R\u1ea5t d\u1ec5 s\u1ea1c v\u00e0o ban \u0111\u00eam.`,
  `N\u1ebfu l\u1ef1a ch\u1ecdn c\u00f3 v\u1ebb \u0111\u01a1n gi\u1ea3n,`,
  `b\u1ea1n kh\u00f4ng ph\u1ea3i ng\u01b0\u1eddi duy nh\u1ea5t ngh\u0129 v\u1eady.`,
  `\u0110\u1ebfn cu\u1ed1i th\u1ebf k\u1ef7 19,`,
  `g\u1ea7n 40% \u00f4 t\u00f4 M\u1ef9 l\u00e0 xe \u0111i\u1ec7n.`,
  `\u1ede c\u00e1c th\u00e0nh ph\u1ed1 c\u00f3 h\u1ec7 th\u1ed1ng \u0111i\u1ec7n ban \u0111\u1ea7u,`,
  `xe \u0111i\u1ec7n l\u00e0 m\u1ed9t l\u1ef1a ch\u1ecdn ph\u1ed5 bi\u1ebfn v\u00e0 \u0111\u00e1ng tin c\u1eady,`,
  `so v\u1edbi c\u00e1c \u0111\u1ed1i th\u1ee7 th\u1ec9nh tho\u1ea3ng ph\u00e1t n\u1ed5.`,
  `Nh\u01b0ng xe \u0111i\u1ec7n c\u00f3 m\u1ed9t v\u1ea5n \u0111\u1ec1 ch\u00ednh:`,
  `pin. Pin \u00f4 t\u00f4 \u0111\u1eddi \u0111\u1ea7u \u0111\u1eaft v\u00e0 kh\u00f4ng hi\u1ec7u qu\u1ea3,`,
  `nhi\u1ec1u nh\u00e0 ph\u00e1t minh bao g\u1ed3m Thomas Edison \u0111\u00e3 c\u1ed1 g\u1eafng t\u1ea1o ra lo\u1ea1i pin c\u00f3 th\u1ec3 l\u01b0u tr\u1eef nhi\u1ec1u \u0111i\u1ec7n h\u01a1n,`,
  `m\u1ed9t s\u1ed1 th\u1eadm ch\u00ed \u0111\u00e3 x\u00e2y d\u1ef1ng c\u00e1c tr\u1ea1m \u0111\u1ed5i pin trong th\u00e0nh ph\u1ed1 \u0111\u1ec3 thay th\u1ebf pin \u0111\u00e3 h\u1ebft.`,
  `Nh\u01b0ng nh\u1eefng bi\u1ec7n ph\u00e1p n\u00e0y v\u1eabn ch\u01b0a \u0111\u1ee7 \u0111\u1ec3 xe \u0111i\u1ec7n \u0111i \u0111\u01b0\u1ee3c qu\u00e3ng \u0111\u01b0\u1eddng d\u00e0i,`,
  `v\u00e0 gi\u00e1 b\u00e1n \u0111\u1eaft g\u1ea5p \u0111\u00f4i xe x\u0103ng.`,
  `Nhi\u1ec1u ng\u01b0\u1eddi kh\u00f4ng \u0111\u1ee7 ti\u1ec1n mua nh\u1eefng m\u00f3n \u0111\u1ed3 xa x\u1ec9 n\u00e0y.`,
  `\u0110\u1ed3ng th\u1eddi, vi\u1ec7c ph\u00e1t hi\u1ec7n ra d\u1ea7u m\u1ecf \u0111\u00e3 l\u00e0m gi\u1ea3m gi\u00e1 x\u0103ng,`,
  `Nh\u1eefng ti\u1ebfn b\u1ed9 c\u00f4ng ngh\u1ec7 m\u1edbi \u0111\u00e3 l\u00e0m cho \u0111\u1ed9ng c\u01a1 \u0111\u1ed1t trong tr\u1edf n\u00ean h\u1ea5p d\u1eabn h\u01a1n.`,
  `H\u1ec7 th\u1ed1ng kh\u1edfi \u0111\u1ed9ng \u0111i\u1ec7n thay th\u1ebf vi\u1ec7c \u0111\u00e1nh l\u1eeda b\u1eb1ng tay quay,`,
  `B\u1ed9 gi\u1ea3m thanh gi\u00fap \u0111\u1ed9ng c\u01a1 \u00eam h\u01a1n,`,
  `V\u00e0 gi\u00e1 \u0111\u1ee1 b\u1eb1ng cao su gi\u00fap \u0111\u1ed9ng c\u01a1 gi\u1ea3m rung.`,
  `N\u0103m 1908,`,
  `Ford \u0111\u00e3 ra m\u1eaft m\u1eabu xe Model T,`,
  `Chi\u1ebfc xe ch\u1ea1y b\u1eb1ng x\u0103ng ch\u1ea5t l\u01b0\u1ee3ng cao, gi\u00e1 c\u1ea3 ph\u1ea3i ch\u0103ng n\u00e0y \u0111\u00e3 thu h\u00fat s\u1ef1 quan t\u00e2m c\u1ee7a c\u00f4ng ch\u00fang.`,
  `\u0110\u1ebfn n\u0103m 1915,`,
  `T\u1ef7 l\u1ec7 xe \u0111i\u1ec7n l\u01b0u th\u00f4ng tr\u00ean \u0111\u01b0\u1eddng \u0111\u00e3 gi\u1ea3m m\u1ea1nh.`,
  `Trong 55 n\u0103m ti\u1ebfp theo,`,
  `\u0110\u1ed9ng c\u01a1 \u0111\u1ed1t trong \u0111\u00e3 th\u1ed1ng tr\u1ecb c\u00e1c con \u0111\u01b0\u1eddng.`,
  `Ngo\u1ea1i tr\u1eeb m\u1ed9t s\u1ed1 lo\u1ea1i xe chuy\u00ean d\u1ee5ng,`,
  `Xe \u0111i\u1ec7n g\u1ea7n nh\u01b0 bi\u1ebfn m\u1ea5t.`,
  `Tuy nhi\u00ean, v\u00e0o nh\u1eefng n\u0103m 1970, xu h\u01b0\u1edbng b\u1eaft \u0111\u1ea7u thay \u0111\u1ed5i.`,
  `M\u1ef9 lo ng\u1ea1i v\u1ec1 ngu\u1ed3n cung d\u1ea7u \u0111\u00e3 kh\u01a1i l\u1ea1i s\u1ef1 quan t\u00e2m \u0111\u1ebfn n\u0103ng l\u01b0\u1ee3ng m\u1edbi.`,
  `V\u00e0o nh\u1eefng n\u0103m 1980,`,
  `c\u00e1c nghi\u00ean c\u1ee9u li\u00ean h\u1ec7 kh\u00ed th\u1ea3i \u00f4 t\u00f4 v\u1edbi s\u01b0\u01a1ng m\u00f9 \u1edf c\u00e1c th\u00e0nh ph\u1ed1 nh\u01b0 Los Angeles,`,
  `\u0111\u00e3 khuy\u1ebfn kh\u00edch ch\u00ednh ph\u1ee7 v\u00e0 c\u00e1c t\u1ed5 ch\u1ee9c b\u1ea3o v\u1ec7 m\u00f4i tr\u01b0\u1eddng xem x\u00e9t l\u1ea1i xe \u0111i\u1ec7n.`,
  `\u0110\u1ebfn l\u00fac n\u00e0y, c\u00e1c h\u00e3ng xe \u0111\u00e3 d\u00e0nh h\u00e0ng th\u1eadp k\u1ef7 \u0111\u1ec3 \u0111\u1ea7u t\u01b0 v\u00e0o \u0111\u1ed9ng c\u01a1 \u0111\u1ed1t trong,`,
  `m\u00e0 kh\u00f4ng d\u00e0nh b\u1ea5t k\u1ef3 ngu\u1ed3n l\u1ef1c n\u00e0o \u0111\u1ec3 gi\u1ea3i quy\u1ebft v\u1ea5n \u0111\u1ec1 pin k\u00e9o d\u00e0i c\u1ea3 th\u1ebf k\u1ef7.`,
  `Nh\u01b0ng c\u00e1c c\u00f4ng ty kh\u00e1c \u0111ang ph\u00e1t tri\u1ec3n c\u00e1c lo\u1ea1i pin ng\u00e0y c\u00e0ng hi\u1ec7u qu\u1ea3,`,
  `\u0111\u1ec3 cung c\u1ea5p n\u0103ng l\u01b0\u1ee3ng cho c\u00e1c thi\u1ebft b\u1ecb \u0111i\u1ec7n t\u1eed c\u1ea7m tay s\u1eed d\u1ee5ng c\u00e1c \u0111\u01b0\u1eddng d\u00e2y m\u1edbi.`,
  `V\u00e0o nh\u1eefng n\u0103m 1990,`,
  `pin nikel-kim lo\u1ea1i hydrua m\u1eadt \u0111\u1ed9 n\u0103ng l\u01b0\u1ee3ng cao \u0111\u00e3 xu\u1ea5t hi\u1ec7n tr\u00ean th\u1ecb tr\u01b0\u1eddng,`,
  `v\u00e0 pin lithium-ion c\u0169ng nhanh ch\u00f3ng ra \u0111\u1eddi.`,
  `C\u00f9ng v\u1edbi c\u00e1c quy \u0111\u1ecbnh gi\u1ea3m s\u01b0\u01a1ng m\u00f9 c\u1ee7a California,`,
  `nh\u1eefng \u0111\u1ed5i m\u1edbi n\u00e0y \u0111\u00e3 t\u1ea1o ra m\u1ed9t l\u00e0n s\u00f3ng xe \u0111i\u1ec7n m\u1edbi,`,
  `bao g\u1ed3m c\u1ea3 xe hybrid.`,
  `Xe hybrid kh\u00f4ng ph\u1ea3i l\u00e0 xe \u0111i\u1ec7n th\u1eadt s\u1ef1,`,
  `Pin NiMH c\u1ee7a ch\u00fang ch\u1ec9 \u0111\u01b0\u1ee3c s\u1eed d\u1ee5ng \u0111\u1ec3 t\u1ed1i \u01b0u h\u00f3a hi\u1ec7u su\u1ea5t c\u1ee7a \u0111\u1ed9ng c\u01a1 x\u0103ng.`,
  `Nh\u01b0ng v\u00e0o n\u0103m 2008,`,
  `Tesla Motors \u0111\u00e3 \u0111\u1ed5i m\u1edbi h\u01a1n n\u1eefa,`,
  `xe th\u1ec3 thao ch\u1ea1y b\u1eb1ng pin lithium-ion c\u1ee7a h\u1ecd \u0111\u00e3 thu h\u00fat s\u1ef1 ch\u00fa \u00fd c\u1ee7a ng\u01b0\u1eddi ti\u00eau d\u00f9ng,`,
  `c\u00e1c nh\u00e0 s\u1ea3n xu\u1ea5t \u00f4 t\u00f4 v\u00e0 c\u01a1 quan qu\u1ea3n l\u00fd.`,
  `Lo\u1ea1i xe \u0111i\u1ec7n thu\u1ea7n t\u00fay n\u00e0y,`,
  `c\u00f3 th\u1ec3 \u0111i \u0111\u01b0\u1ee3c h\u01a1n 320 km ch\u1ec9 v\u1edbi m\u1ed9t l\u1ea7n s\u1ea1c,`,
  `g\u1ea7n g\u1ea5p \u0111\u00f4i k\u1ef7 l\u1ee5c tr\u01b0\u1edbc \u0111\u00e2y.`,
  `T\u1eeb \u0111\u00f3 tr\u1edf \u0111i, xe \u0111i\u1ec7n \u0111\u00e3 c\u1ea3i thi\u1ec7n \u0111\u00e1ng k\u1ec3 v\u1ec1 chi ph\u00ed,`,
  `hi\u1ec7u su\u1ea5t, hi\u1ec7u qu\u1ea3 v\u00e0 kh\u1ea3 n\u0103ng ti\u1ebfp c\u1eadn,`,
  `ch\u00fang t\u0103ng t\u1ed1c nhanh h\u01a1n nhi\u1ec1u so v\u1edbi xe th\u1ec3 thao ch\u1ea1y b\u1eb1ng x\u0103ng.`,
  `M\u1eb7c d\u00f9 chi ph\u00ed ban \u0111\u1ea7u c\u1ee7a m\u1ed9t s\u1ed1 m\u1eabu xe v\u1eabn c\u00f2n cao,`,
  `v\u1ec1 l\u00e2u d\u00e0i,`,
  `ch\u00fang th\u1ef1c s\u1ef1 \u0111\u00e3 ti\u1ebft ki\u1ec7m ti\u1ec1n cho ch\u1ee7 s\u1edf h\u1eefu.`,
  `Khi c\u00e1c ch\u00ednh ph\u1ee7 tr\u00ean th\u1ebf gi\u1edbi t\u1eadp trung v\u00e0o vi\u1ec7c gi\u1ea3m thi\u1ec3u bi\u1ebfn \u0111\u1ed5i kh\u00ed h\u1eadu,`,
  `\u00d4 t\u00f4 \u0111i\u1ec7n \u0111\u01b0\u1ee3c k\u1ef3 v\u1ecdng s\u1ebd thay th\u1ebf ho\u00e0n to\u00e0n xe ch\u1ea1y b\u1eb1ng x\u0103ng.`,
  `T\u1ea1i Na Uy, doanh s\u1ed1 b\u00e1n \u00f4 t\u00f4 n\u0103m 2020,`,
  `xe \u0111i\u1ec7n chi\u1ebfm 75%.`,
  `C\u00e1c s\u1eafc l\u1ec7nh v\u1ec1 xe kh\u00f4ng ph\u00e1t th\u1ea3i \u1edf California v\u00e0 c\u00e1c ch\u00ednh s\u00e1ch gi\u1ea3m ph\u00e1t th\u1ea3i t\u00edch c\u1ef1c \u1edf Ch\u00e2u \u00c2u,`,
  `\u0111\u00e3 l\u00e0m ch\u1eadm \u0111\u00e1ng k\u1ec3 \u0111\u1ea7u t\u01b0 to\u00e0n c\u1ea7u v\u00e0o xe ch\u1ea1y b\u1eb1ng x\u0103ng.`,
  `Ch\u1eb3ng bao l\u00e2u n\u1eefa, \u00f4 t\u00f4 \u0111i\u1ec7n s\u1ebd chi\u1ebfm \u01b0u th\u1ebf tr\u1edf l\u1ea1i,`,
  `v\u01b0\u1ee3t xa xe ch\u1ea1y b\u1eb1ng x\u0103ng.`,
  `B\u1ea1n mu\u1ed1n t\u00ecm hi\u1ec3u th\u00eam v\u1ec1 c\u00e1c nh\u00e0 khoa h\u1ecdc,`,
  `c\u00e1c nh\u00e0 ho\u1ea1ch \u0111\u1ecbnh ch\u00ednh s\u00e1ch v\u00e0 nh\u1eefng ng\u01b0\u1eddi nh\u01b0 b\u1ea1n \u0111ang th\u1ef1c hi\u1ec7n nh\u1eefng bi\u1ec7n ph\u00e1p th\u00fa v\u1ecb \u0111\u1ec3 \u0111\u1ea3m b\u1ea3o t\u01b0\u01a1ng lai c\u1ee7a Tr\u00e1i \u0110\u1ea5t?`,
  `H\u00e3y truy c\u1eadp idotide.com/earthgoo \u0111\u1ec3 th\u1ecfa m\u00e3n tr\u00ed t\u00f2 m\u00f2 v\u00e0 hy v\u1ecdng c\u1ee7a b\u1ea1n.`,
];

