const TEDED_SMARTEST_AGE_IQJ9EPFRRKI_TRANSLATIONS = [
  `Ng\u01b0\u1eddi \u1edf \u0111\u1ed9 tu\u1ed5i n\u00e0o l\u00e0 th\u00f4ng minh nh\u1ea5t?`,
  `C\u00f3 l\u1ebd tham gia m\u1ed9t cu\u1ed9c thi \u0111\u1ea5u t\u00ecnh b\u1ea1n s\u1ebd cho t\u00f4i c\u00e2u tr\u1ea3 l\u1eddi.`,
  `N\u0103m t\u1edbi l\u00e0 cu\u1ed9c thi Tranh \u0110o\u1ea1t Tr\u00ed Tu\u1ec7 th\u01b0\u1eddng ni\u00ean,`,
  `10 \u0111\u1ed9i g\u1ed3m hai ng\u01b0\u1eddi s\u1ebd c\u1ea1nh tranh trong m\u1ed9t cu\u1ed9c thi m\u01b0\u1eddi m\u00f4n ph\u1ed1i h\u1ee3p bao g\u1ed3m c\u00e1c th\u1eed th\u00e1ch tr\u00ed tu\u1ec7,`,
  `\u0111\u1ed1 vui ki\u1ebfn th\u1ee9c v\u00e0 gi\u1ea3i \u0111\u1ed1.`,
  `T\u00f4i \u0111\u00e3 chu\u1ea9n b\u1ecb cho vi\u1ec7c n\u00e0y m\u1ed9t n\u0103m,`,
  `c\u1ea7n ch\u1ecdn ng\u01b0\u1eddi \u0111\u1ed3ng \u0111\u1ed9i th\u00f4ng minh nh\u1ea5t,`,
  `c\u00f3 n\u0103ng l\u1ef1c nh\u1ea5t,`,
  `v\u00e0 l\u1eadp danh s\u00e1ch m\u1ed9t s\u1ed1 \u1ee9ng c\u1eed vi\u00ean ti\u1ec1m n\u0103ng.`,
  `\u0110\u1ea7u ti\u00ean l\u00e0 Gabriela, c\u00f4 b\u00e9 ch\u1ec9 m\u1edbi 8 tu\u1ed5i, nh\u01b0ng \u0111\u1eebng \u0111\u00e1nh gi\u00e1 th\u1ea5p c\u00f4 b\u00e9,`,
  `c\u00f4 b\u00e9 c\u00f3 th\u1ec3 n\u00f3i l\u01b0u lo\u00e1t hai ng\u00f4n ng\u1eef,`,
  `v\u00e0 c\u0169ng l\u00e0 m\u1ed9t ng\u01b0\u1eddi c\u1ef1c k\u1ef3 s\u00e1ng t\u1ea1o.`,
  `Th\u1ee9 hai l\u00e0 Emma, c\u00f4 \u1ea5y c\u00f3 th\u1ec3 \u0111\u1ecdc thu\u1ed9c 100 ch\u1eef s\u1ed1 \u0111\u1ea7u ti\u00ean c\u1ee7a s\u1ed1 pi,`,
  `ki\u1ebfm s\u1ed1ng b\u1eb1ng vi\u1ec7c thi\u1ebft k\u1ebf v\u1ec7 tinh,`,
  `v\u00e0 gi\u1ecfi l\u00e0m m\u00f3n b\u00e1nh souffl\u00e9 ho\u00e0n h\u1ea3o.`,
  `Ho\u1eb7c t\u00f4i c\u00f3 th\u1ec3 ch\u1ecdn \u00f4ng Taylor,`,
  `ng\u01b0\u1eddi ch\u01a1i c\u1edd gi\u1ecfi nh\u1ea5t khu ph\u1ed1,`,
  `ch\u01b0a k\u1ec3 \u00f4ng \u1ea5y \u0111\u00e3 tham gia h\u01a1n 20 cu\u1ed9c thi Brain Brawl,`,
  `v\u00e0 th\u1eafng 5 l\u1ea7n.`,
  `T\u00f4i kh\u00f4ng ch\u1eafc n\u00ean ch\u1ecdn ai,`,
  `ai l\u00e0 ng\u01b0\u1eddi th\u00f4ng minh nh\u1ea5t?`,
  `T\u00f4i n\u00ean ch\u1ecdn ai l\u00e0m \u0111\u1ed3ng \u0111\u1ed9i cho tr\u1eadn \u0111\u1ea5u ng\u00e0y mai?`,
  `V\u00e0 t\u1ea1i sao l\u1ea1i l\u00e0 ng\u01b0\u1eddi \u0111\u00f3?`,
  `Ch\u00e0, \u0111i\u1ec1u \u0111\u00f3 ph\u1ee5 thu\u1ed9c.`,
  `M\u1eb7c d\u00f9 tr\u00ed th\u00f4ng minh th\u01b0\u1eddng g\u1eafn li\u1ec1n v\u1edbi c\u00e1c b\u00e0i ki\u1ec3m tra IQ,`,
  `nh\u01b0ng nh\u1eefng b\u00e0i ki\u1ec3m tra n\u00e0y th\u01b0\u1eddng b\u1ecf qua ph\u1ea1m vi v\u00e0 chi\u1ec1u s\u00e2u kh\u1ea3 n\u0103ng c\u1ee7a m\u1ed9t ng\u01b0\u1eddi.`,
  `V\u00ec v\u1eady, ch\u00fang ta s\u1ebd chia kh\u00e1i ni\u1ec7m v\u1ec1`,
  `v\u00e0 kh\u1ea3 n\u0103ng h\u1ecdc h\u1ecfi, v.v.,`,
  `v\u00e0 kh\u00e1m ph\u00e1 xem n\u00e3o b\u1ed9 ho\u1ea1t \u0111\u1ed9ng t\u1ed1t nh\u1ea5t khi n\u00e0o cho m\u1ed7i lo\u1ea1i.`,
  `H\u00e3y b\u1eaft \u0111\u1ea7u t\u1eeb \u0111\u1ea7u.`,
  `Trong nh\u1eefng n\u0103m \u0111\u1ea7u \u0111\u1eddi,`,
  `n\u00e3o b\u1ed9 c\u1ee7a b\u1ea1n ph\u00e1t tri\u1ec3n nhanh ch\u00f3ng,`,
  `\u0111\u01b0\u1ee3c g\u1ecdi l\u00e0 h\u00ecnh th\u00e0nh kh\u1edbp th\u1ea7n kinh,`,
  `t\u1ea1o ra h\u01a1n 1 tri\u1ec7u k\u1ebft n\u1ed1i th\u1ea7n kinh m\u1edbi m\u1ed7i gi\u00e2y.`,
  `Khi n\u00e3o b\u1ed9 ph\u00e1t tri\u1ec3n, n\u00f3 tr\u1ea3i qua qu\u00e1 tr\u00ecnh tinh ch\u1ec9nh,`,
  `d\u1ef1a tr\u00ean tr\u1ea3i nghi\u1ec7m v\u00e0 m\u00f4i tr\u01b0\u1eddng c\u1ee7a b\u1ea1n,`,
  `c\u00e1c k\u1ebft n\u1ed1i \u0111\u01b0\u1ee3c s\u1eed d\u1ee5ng s\u1ebd \u0111\u01b0\u1ee3c c\u1ee7ng c\u1ed1,`,
  `c\u00e1c k\u1ebft n\u1ed1i kh\u00f4ng s\u1eed d\u1ee5ng s\u1ebd b\u1ecb lo\u1ea1i b\u1ecf.`,
  `C\u00e1c \u0111\u01b0\u1eddng d\u1eabn th\u1ea7n kinh \u0111\u01b0\u1ee3c s\u1eed d\u1ee5ng th\u01b0\u1eddng xuy\u00ean c\u00f3 myelin,`,
  `\u0111\u01b0\u1ee3c bao b\u1ecdc trong m\u1ed9t l\u1edbp c\u00e1ch \u0111i\u1ec7n,`,
  `l\u00e0m cho th\u00f4ng tin truy\u1ec1n \u0111i nhanh h\u01a1n,`,
  `\u0111i\u1ec1u n\u00e0y t\u1ea1o ra m\u1ed9t b\u1ed9 n\u00e3o hi\u1ec7u qu\u1ea3,`,
  `tinh vi h\u01a1n.`,
  `Nh\u01b0ng qu\u00e1 tr\u00ecnh t\u00e1i t\u1ea1o n\u00e3o n\u00e0y di\u1ec5n ra v\u00e0o nh\u1eefng th\u1eddi \u0111i\u1ec3m kh\u00e1c nhau,`,
  `b\u00ean trong v\u00e0 gi\u1eefa c\u00e1c v\u00f9ng n\u00e3o,`,
  `ph\u00e1t tri\u1ec3n \u1edf nh\u1eefng \u0111\u1ed9 tu\u1ed5i kh\u00e1c nhau.`,
  `V\u00ed d\u1ee5, khi c\u00f2n nh\u1ecf,`,
  `ph\u1ea7n n\u00e3o b\u1ed9 li\u00ean quan \u0111\u1ebfn vi\u1ec7c h\u1ecdc ng\u00f4n ng\u1eef ph\u00e1t tri\u1ec3n \u0111\u1eb7c bi\u1ec7t nhanh ch\u00f3ng,`,
  `\u0111\u00e2y c\u0169ng l\u00e0 l\u00fd do t\u1ea1i sao nhi\u1ec1u tr\u1ebb em c\u00f3 th\u1ec3 h\u1ecdc v\u00e0 th\u00e0nh th\u1ea1o nhi\u1ec1u ng\u00f4n ng\u1eef.`,
  `Tuy nhi\u00ean, v\u1ecf n\u00e3o tr\u01b0\u1edbc tr\u00e1n,`,
  `m\u1ed9t ph\u1ea7n n\u00e3o b\u1ed9 ch\u1ecbu tr\u00e1ch nhi\u1ec7m ki\u1ec3m so\u00e1t nh\u1eadn th\u1ee9c v\u00e0 \u00fd ch\u00ed, l\u1ea1i ph\u00e1t tri\u1ec3n ch\u1eadm.`,
  `Do \u0111\u00f3, nhi\u1ec1u tr\u1ebb nh\u1ecf c\u00f3 th\u1ec3 kh\u00f4ng gi\u1ecfi c\u00e1c tr\u00f2 ch\u01a1i chi\u1ebfn l\u01b0\u1ee3c,`,
  `nh\u01b0 c\u1edd vua ho\u1eb7c c\u1edd caro,`,
  `nh\u1eefng tr\u00f2 \u0111\u00f2i h\u1ecfi s\u1ef1 t\u1eadp trung li\u00ean t\u1ee5c,`,
  `l\u1eadp k\u1ebf ho\u1ea1ch v\u00e0 t\u01b0 duy tr\u1eebu t\u01b0\u1ee3ng.`,
  `\u0110\u1ed3ng th\u1eddi, tr\u1ebb em c\u00f3 xu h\u01b0\u1edbng h\u1ecdc kh\u00e1m ph\u00e1 t\u1ef1 do,`,
  `ch\u00fang gi\u1ea3i quy\u1ebft c\u00e1c c\u00e2u \u0111\u1ed1 b\u1eb1ng nh\u1eefng ph\u01b0\u01a1ng ph\u00e1p gi\u00e0u tr\u00ed t\u01b0\u1edfng t\u01b0\u1ee3ng h\u01a1n,`,
  `v\u00e0 ph\u1ea7n l\u1edbn \u00edt s\u1ee3 m\u1eafc l\u1ed7i.`,
  `Nh\u01b0ng ng\u01b0\u1eddi l\u1edbn c\u00f3 nh\u1eefng kh\u1ea3 n\u0103ng \u0111\u1ed9c \u0111\u00e1o c\u1ee7a ri\u00eang h\u1ecd.`,
  `Ng\u01b0\u1eddi l\u1edbn \u0111\u01b0\u1ee3c h\u01b0\u1edfng l\u1ee3i t\u1eeb v\u1ecf n\u00e3o tr\u01b0\u1edbc tr\u00e1n ph\u00e1t tri\u1ec3n v\u01b0\u1ee3t tr\u1ed9i,`,
  `Gi\u00fap h\u1ecd th\u1ef1c hi\u1ec7n t\u1ed1t h\u01a1n c\u00e1c k\u1ef9 n\u0103ng c\u1ea7n h\u1ecdc h\u1ecfi,`,
  `s\u1ef1 t\u1eadp trung v\u00e0 ghi nh\u1edb.`,
  `H\u1ecd c\u00f3 th\u1ec3 gi\u1ea3i c\u00e2u \u0111\u1ed1 ho\u1eb7c tr\u00f2 ch\u01a1i \u00f4 ch\u1eef nhanh v\u00e0 hi\u1ec7u qu\u1ea3 h\u01a1n.`,
  `\u1ede tu\u1ed5i tr\u01b0\u1edfng th\u00e0nh, khi v\u00f9ng hippocampus (trung t\u00e2m tr\u00ed nh\u1edb c\u1ee7a n\u00e3o) b\u1ecb l\u00e3o h\u00f3a,`,
  `nh\u1eefng k\u1ef9 n\u0103ng n\u00e0y c\u00f3 th\u1ec3 suy gi\u1ea3m.`,
  `Nh\u01b0ng c\u00e2u n\u00f3i g\u1eebng c\u00e0ng gi\u00e0 c\u00e0ng cay c\u0169ng c\u00f3 c\u01a1 s\u1edf khoa h\u1ecdc.`,
  `Nh\u1edd h\u1ecdc h\u1ecfi su\u1ed1t \u0111\u1eddi,`,
  `ng\u01b0\u1eddi l\u1edbn tu\u1ed5i c\u00f3 nhi\u1ec1u ki\u1ebfn th\u1ee9c h\u01a1n \u0111\u1ec3 h\u1ed3i t\u01b0\u1edfng v\u00e0 s\u1eed d\u1ee5ng,`,
  `gi\u00fap h\u1ecd c\u00f3 l\u1ee3i th\u1ebf h\u01a1n trong c\u00e1c c\u00e2u \u0111\u1ed1 ki\u1ebfn th\u1ee9c t\u1ed5ng qu\u00e1t.`,
  `C\u00e1c y\u1ebfu t\u1ed1 kh\u00e1c c\u1ea7n xem x\u00e9t, bao g\u1ed3m c\u1ea3 \u0111i\u1ec3m m\u1ea1nh c\u1ee7a ch\u00ednh ng\u01b0\u1eddi \u0111\u00f3.`,
  `\u1ede tu\u1ed5i thi\u1ebfu ni\u00ean,`,
  `v\u00f9ng v\u1ecf n\u00e3o tr\u01b0\u1edbc tr\u00e1n ph\u00e1t tri\u1ec3n h\u01a1n so v\u1edbi th\u1eddi th\u01a1 \u1ea5u,`,
  `\u0111i\u1ec1u n\u00e0y gi\u00fap b\u1ea1n t\u01b0 duy logic h\u01a1n v\u00e0 gi\u1ecfi gi\u1ea3i c\u00e1c b\u00e0i to\u00e1n.`,
  `\u0110\u1ed3ng th\u1eddi, s\u00e2u b\u00ean trong n\u00e3o c\u1ee7a b\u1ea1n,`,
  `v\u00f9ng n\u00e3o \u0111\u00f3ng vai tr\u00f2 quan tr\u1ecdng trong \u0111\u1ed9ng l\u1ef1c v\u00e0 ph\u1ea7n th\u01b0\u1edfng c\u0169ng ph\u00e1t tri\u1ec3n nhanh ch\u00f3ng,`,
  `th\u00fac \u0111\u1ea9y nh\u1eefng thanh thi\u1ebfu ni\u00ean nh\u01b0 Emir tr\u1edf th\u00e0nh nh\u1eefng ng\u01b0\u1eddi ham h\u1ecdc h\u1ecfi,`,
  `c\u00f3 tinh th\u1ea7n phi\u00eau l\u01b0u v\u00e0 kh\u00f4ng ng\u1eebng h\u1ecdc h\u1ecfi.`,
  `Theo nhi\u1ec1u c\u00e1ch,`,
  `b\u1ea1n c\u00f3 th\u1ec3 coi thanh thi\u1ebfu ni\u00ean l\u00e0 m\u1ed9t ng\u01b0\u1eddi \u0111a n\u0103ng,`,
  `b\u1ed9 n\u00e3o c\u1ee7a h\u1ecd d\u00e1m t\u00ecm ki\u1ebfm nh\u1eefng tr\u1ea3i nghi\u1ec7m m\u1edbi v\u00e0 h\u1ecdc h\u1ecfi nhanh ch\u00f3ng.`,
  `B\u1ea1n \u0111ang \u1edf trong m\u1ed9t giai \u0111o\u1ea1n n\u0103ng \u0111\u1ed9ng,`,
  `nh\u1eefng l\u1ef1a ch\u1ecdn b\u1ea1n \u0111\u01b0a ra v\u00e0 nh\u1eefng k\u1ef9 n\u0103ng b\u1ea1n t\u1eadp trung v\u00e0o,`,
  `th\u1ef1c s\u1ef1 c\u00f3 th\u1ec3 \u0111\u1ecbnh h\u01b0\u1edbng s\u1ef1 ph\u00e1t tri\u1ec3n c\u1ee7a n\u00e3o b\u1ed9 b\u1ea1n.`,
  `V\u1eady \u0111\u1ed9 tu\u1ed5i n\u00e0o l\u00e0 th\u00f4ng minh nh\u1ea5t?`,
  `Kh\u00f4ng c\u00f3 c\u00e2u tr\u1ea3 l\u1eddi duy nh\u1ea5t,`,
  `c\u00f3 th\u1ec3 l\u00e0 8 tu\u1ed5i,`,
  `16 tu\u1ed5i, 25 tu\u1ed5i,`,
  `65 tu\u1ed5i v\u00e0 b\u1ea5t k\u1ef3 \u0111\u1ed9 tu\u1ed5i n\u00e0o \u1edf gi\u1eefa.`,
  `B\u1ed9 n\u00e3o c\u1ee7a ch\u00fang ta t\u1eadp trung ph\u00e1t tri\u1ec3n c\u00e1c k\u1ef9 n\u0103ng kh\u00e1c nhau \u1edf c\u00e1c giai \u0111o\u1ea1n kh\u00e1c nhau trong cu\u1ed9c \u0111\u1eddi,`,
  `\u0111\u1ec3 \u0111\u1ed1i ph\u00f3 v\u1edbi nh\u1eefng th\u00e1ch th\u1ee9c v\u00e0 nhu c\u1ea7u t\u01b0\u01a1ng \u1ee9ng trong cu\u1ed9c s\u1ed1ng.`,
  `V\u00ec v\u1eady, b\u1ea5t k\u1ec3 Emir ch\u1ecdn ai,`,
  `C\u00f3 m\u1ed9t \u0111\u1ed9i ng\u0169 \u0111a th\u1ebf h\u1ec7 m\u1edbi l\u00e0 chi\u1ebfn l\u01b0\u1ee3c t\u1ed1t.`,
  `H\u00e3y ti\u1ebfp t\u1ee5c h\u1ecdc h\u1ecfi qua nh\u1eefng video n\u00e0y,`,
  `V\u00e0 \u0111\u1eebng qu\u00ean \u0111\u0103ng k\u00fd,`,
  `\u0110\u1eebng b\u1ecf l\u1ee1 c\u01a1 h\u1ed9i h\u1ecdc h\u1ecfi nh\u1eefng \u0111i\u1ec1u m\u1edbi m\u1ebb.`,
];

