const TEDED_ZODIAC_MYTHS_3QKXWEXQEQ8_TRANSLATIONS = [
  `Tu\u1ed5i c\u1ee7a b\u1ea1n l\u00e0 g\u00ec?`,
  `Theo chi\u00eam tinh h\u1ecdc ph\u01b0\u01a1ng T\u00e2y,`,
  `cung ho\u00e0ng \u0111\u1ea1o \u0111\u01b0\u1ee3c x\u00e1c \u0111\u1ecbnh b\u1edfi ng\u00e0y sinh.`,
  `Nh\u01b0ng theo 12 con gi\u00e1p c\u1ee7a Trung Qu\u1ed1c,`,
  `hay c\u00f2n g\u1ecdi l\u00e0 "sinh ti\u00eau",`,
  `t\u1ee9c l\u00e0 con gi\u00e1p c\u1ee7a b\u1ea1n,`,
  `\u0111\u1ec1 c\u1eadp \u0111\u1ebfn con v\u1eadt \u0111\u1ea1i di\u1ec7n cho n\u0103m sinh c\u1ee7a b\u1ea1n.`,
  `Trong s\u1ed1 nhi\u1ec1u truy\u1ec1n thuy\u1ebft gi\u1ea3i th\u00edch ngu\u1ed3n g\u1ed1c v\u00e0 th\u1ee9 t\u1ef1 c\u1ee7a 12 con gi\u00e1p,`,
  `c\u00e2u chuy\u1ec7n cu\u1ed9c thi v\u01b0\u1ee3t s\u00f4ng l\u00e0 ph\u1ed5 bi\u1ebfn nh\u1ea5t.`,
  `Truy\u1ec1n thuy\u1ebft k\u1ec3 r\u1eb1ng, Ng\u1ecdc Ho\u00e0ng, ng\u01b0\u1eddi cai tr\u1ecb thi\u00ean \u0111\u00ecnh, mu\u1ed1n t\u1ea1o ra m\u1ed9t c\u00e1ch \u0111\u1ec3 \u0111o th\u1eddi gian,`,
  `v\u00ec v\u1eady ng\u00e0i \u0111\u00e3 t\u1ed5 ch\u1ee9c m\u1ed9t cu\u1ed9c thi.`,
  `12 con v\u1eadt \u0111\u1ea7u ti\u00ean v\u01b0\u1ee3t s\u00f4ng,`,
  `c\u00f3 th\u1ec3 tr\u1edf th\u00e0nh n\u0103m c\u1ee7a \u00e2m l\u1ecbch theo th\u1ee9 t\u1ef1 ch\u00fang \u0111\u1ebfn n\u01a1i.`,
  `Chu\u1ed9t \u0111\u00e3 d\u1eady r\u1ea5t s\u1edbm cho vi\u1ec7c n\u00e0y,`,
  `nh\u01b0ng khi v\u01b0\u1ee3t s\u00f4ng n\u00f3 g\u1eb7p ng\u1ef1a,`,
  `H\u1ed5 v\u00e0 Tr\u00e2u. V\u00ec chu\u1ed9t r\u1ea5t nh\u1ecf v\u00e0 kh\u00f4ng bi\u1ebft b\u01a1i nhi\u1ec1u,`,
  `N\u00f3 \u0111\u00e3 nh\u1edd nh\u1eefng con v\u1eadt to l\u1edbn h\u01a1n gi\u00fap \u0111\u1ee1.`,
  `Nh\u01b0ng H\u1ed5 v\u00e0 Ng\u1ef1a \u0111\u1ec1u t\u1eeb ch\u1ed1i n\u00f3.`,
  `Tr\u00e2u t\u1ed1t b\u1ee5ng \u0111\u1ed3ng \u00fd c\u00f5ng chu\u1ed9t qua s\u00f4ng,`,
  `Nh\u01b0ng khi ch\u00fang s\u1eafp \u0111\u1ebfn b\u1edd,`,
  `Chu\u1ed9t \u0111\u00e3 nh\u1ea3y t\u1eeb \u0111\u1ea7u tr\u00e2u l\u00ean b\u1edd v\u00e0 gi\u00e0nh v\u1ecb tr\u00ed th\u1ee9 nh\u1ea5t,`,
  `C\u00f2n Tr\u00e2u th\u00ec v\u1ec1 th\u1ee9 hai.`,
  `Theo s\u00e1t ph\u00eda sau l\u00e0 H\u1ed5 d\u0169ng m\u00e3nh.`,
  `Th\u1ecf qu\u00e1 nh\u1ecf b\u00e9,`,
  `Kh\u00f4ng th\u1ec3 b\u01a1i qua d\u00f2ng s\u00f4ng ch\u1ea3y xi\u1ebft, nh\u01b0ng n\u00f3 \u0111\u00e3 nhanh nh\u1eb9n nh\u1ea3y qua nh\u1eefng t\u1ea3ng \u0111\u00e1 v\u00e0 kh\u00fac g\u1ed7 tr\u00f4i \u0111\u1ec3 gi\u00e0nh v\u1ecb tr\u00ed th\u1ee9 t\u01b0.`,
  `Ti\u1ebfp theo l\u00e0 R\u1ed3ng, l\u1ebd ra n\u00f3 c\u00f3 th\u1ec3 bay th\u1eb3ng qua,`,
  `Nh\u01b0ng n\u00f3 \u0111\u00e3 d\u1eebng l\u1ea1i tr\u00ean \u0111\u01b0\u1eddng \u0111\u1ec3 gi\u00fap nh\u1eefng con v\u1eadt m\u00e0 n\u00f3 g\u1eb7p tr\u00ean \u0111\u01b0\u1eddng qua s\u00f4ng.`,
  `Sau \u0111\u00f3 l\u00e0 Ng\u1ef1a, phi n\u01b0\u1edbc \u0111\u1ea1i b\u0103ng qua s\u00f4ng.`,
  `Nh\u01b0ng \u0111\u00fang l\u00fac Ng\u1ef1a s\u1eafp \u0111\u1ebfn b\u1edd b\u00ean kia,`,
  `R\u1eafn \u0111\u00e3 tr\u01b0\u1ee3t \u0111\u1ebfn ch\u00e2n n\u00f3,`,
  `khi\u1ebfn ng\u1ef1a s\u1ee3 h\u00e3i gi\u01a1 v\u00f3 tr\u01b0\u1edbc l\u00ean,`,
  `\u0111\u1ec3 r\u1eafn v\u1ec1 th\u1ee9 s\u00e1u.`,
  `L\u00fac n\u00e0y Ng\u1ecdc Ho\u00e0ng nh\u00ecn v\u1ec1 ph\u00eda b\u1edd s\u00f4ng,`,
  `ph\u00e1t hi\u1ec7n D\u00ea, Kh\u1ec9 v\u00e0 G\u00e0 \u0111ang ng\u1ed3i tr\u00ean c\u00f9ng m\u1ed9t chi\u1ebfc b\u00e8,`,
  `c\u00f9ng nhau ch\u00e8o b\u00e8 qua \u0111\u00e1m c\u1ecf n\u01b0\u1edbc.`,
  `Khi ch\u00fang c\u00f9ng \u0111\u1ebfn \u0111\u00edch,`,
  `m\u1ecdi ng\u01b0\u1eddi \u0111\u1ed3ng \u00fd trao h\u1ea1ng t\u00e1m cho D\u00ea,`,
  `v\u00ec n\u00f3 lu\u00f4n \u0111\u1ed9ng vi\u00ean \u0111\u1ed3ng \u0111\u1ed9i tr\u00ean \u0111\u01b0\u1eddng \u0111i,`,
  `gi\u00fap c\u1ea3 \u0111\u1ed9i ph\u1ed1i h\u1ee3p \u0103n \u00fd.`,
  `Sau \u0111\u00f3 l\u00e0 Kh\u1ec9 v\u00e0 G\u00e0.`,
  `Ti\u1ebfp theo l\u00e0 Ch\u00f3 b\u01a1i l\u00ean b\u1edd.`,
  `Ch\u00f3 v\u1ed1n d\u0129 b\u01a1i r\u1ea5t gi\u1ecfi,`,
  `nh\u01b0ng v\u00ec m\u1ea3i ch\u01a1i \u0111\u00f9a d\u01b0\u1edbi n\u01b0\u1edbc qu\u00e1 l\u00e2u, cu\u1ed1i c\u00f9ng n\u00f3 ch\u1ec9 v\u1ec1 th\u1ee9 m\u01b0\u1eddi m\u1ed9t.`,
  `Cu\u1ed1i c\u00f9ng l\u00e0 H\u1ee3i,`,
  `tr\u00ean \u0111\u01b0\u1eddng \u0111i n\u00f3 \u0111\u00f3i b\u1ee5ng n\u00ean d\u1eebng l\u1ea1i \u0103n r\u1ed3i ng\u1ee7 g\u1eadt,`,
  `cu\u1ed1i c\u00f9ng m\u1edbi lo\u1ea1ng cho\u1ea1ng b\u01b0\u1edbc qua v\u1ea1ch \u0111\u00edch.`,
  `T\u1eeb \u0111\u00f3, c\u00e1c con v\u1eadt n\u00e0y l\u1ea7n l\u01b0\u1ee3t t\u01b0\u01a1ng \u1ee9ng v\u1edbi c\u00e1c n\u0103m kh\u00e1c nhau.`,
  `M\u1ed7i 60 n\u0103m l\u00e0 m\u1ed9t chu k\u1ef3,`,
  `T\u1ea1i sao l\u1ea1i l\u00e0 60 m\u00e0 kh\u00f4ng ph\u1ea3i 12?`,
  `V\u00ec l\u1ecbch truy\u1ec1n th\u1ed1ng Trung Qu\u1ed1c c\u00f3 hai h\u1ec7 th\u1ed1ng t\u00ednh gi\u1edd k\u1ebft h\u1ee3p v\u1edbi nhau.`,
  `H\u1ec7 th\u1ed1ng ni\u00ean \u0111\u1ea1i t\u01b0\u01a1ng \u1ee9ng v\u1edbi 12 con gi\u00e1p,`,
  `li\u00ean quan \u0111\u1ebfn h\u1ec7 th\u1ed1ng g\u1ecdi l\u00e0 'Th\u1eadp nh\u1ecb \u0110\u1ecba chi'.`,
  `M\u1ed9t h\u1ec7 th\u1ed1ng ni\u00ean \u0111\u1ea1i kh\u00e1c,`,
  `Th\u1eadp Thi\u00ean can, \u0111\u01b0\u1ee3c t\u1ea1o th\u00e0nh t\u1eeb n\u0103m y\u1ebfu t\u1ed1 truy\u1ec1n th\u1ed1ng:`,
  `Kim, M\u1ed9c, Th\u1ee7y, H\u1ecfa, Th\u1ed5.`,
  `M\u1ed7i y\u1ebfu t\u1ed1 l\u1ea1i chia th\u00e0nh \u00e2m,`,
  `d\u01b0\u01a1ng, t\u1ea1o ra m\u1ed9t chu k\u1ef3 m\u01b0\u1eddi n\u0103m.`,
  `Khi 12 con gi\u00e1p \u0110\u1ecba chi v\u00e0 n\u0103m y\u1ebfu t\u1ed1 k\u1ebft h\u1ee3p,`,
  `th\u00eam \u00e2m ho\u1eb7c d\u01b0\u01a1ng c\u1ee7a Thi\u00ean can,`,
  `t\u1ea1o ra 60 s\u1ef1 k\u1ebft h\u1ee3p kh\u00e1c nhau trong 60 n\u0103m,`,
  `\u0111\u01b0\u1ee3c g\u1ecdi l\u00e0 "m\u1ed9t can-chi".`,
  `V\u00ec v\u1eady, ng\u01b0\u1eddi sinh n\u0103m 1980 l\u00e0 tu\u1ed5i M\u00f9i,`,
  `Kim, thu\u1ed9c kh\u1ec9, c\u00f2n ng\u01b0\u1eddi sinh n\u0103m 2007 th\u00ec l\u00e0 \u00c2m,`,
  `H\u1ecfa, tu\u1ed5i H\u1ee3i. Th\u1ef1c t\u1ebf,`,
  `b\u1ea1n c\u00f3 th\u1ec3 t\u00ednh con gi\u00e1p b\u00ean trong c\u1ee7a m\u00ecnh theo th\u00e1ng sinh,`,
  `con gi\u00e1p th\u1eadt theo ng\u00e0y sinh,`,
  `v\u00e0 con gi\u00e1p b\u00ed \u1ea9n theo gi\u1edd sinh c\u1ee7a b\u1ea1n.`,
  `Cu\u1ed9c thi v\u01b0\u1ee3t s\u00f4ng \u0111\u00e3 x\u00e1c \u0111\u1ecbnh nh\u1eefng con v\u1eadt n\u00e0o l\u00e0 12 con gi\u00e1p c\u1ee7a Trung Qu\u1ed1c,`,
  `nh\u01b0ng khi h\u1ec7 th\u1ed1ng ho\u00e0ng \u0111\u1ea1o lan r\u1ed9ng kh\u1eafp ch\u00e2u \u00c1,`,
  `c\u00e1c qu\u1ed1c gia kh\u00e1c \u0111\u00e3 \u0111i\u1ec1u ch\u1ec9nh h\u1ec7 th\u1ed1ng ho\u00e0ng \u0111\u1ea1o`,
  `\u0111\u1ec3 ph\u00f9 h\u1ee3p v\u1edbi v\u0103n h\u00f3a d\u00e2n t\u1ed9c c\u1ee7a h\u1ecd.`,
  `Do \u0111\u00f3, trong v\u00f2ng ho\u00e0ng \u0111\u1ea1o Vi\u1ec7t Nam, b\u1ea1n c\u00f3 th\u1ec3 th\u1ea5y m\u00ecnh tu\u1ed5i M\u00e3o thay v\u00ec tu\u1ed5i Th\u1ecf.`,
  `N\u1ebfu b\u1ea1n \u1edf Th\u00e1i Lan,`,
  `r\u1eafn th\u1ea7n Naga thay th\u1ebf lo\u00e0i r\u1ed3ng.`,
  `D\u00f9 b\u1ea1n tin hay kh\u00f4ng,`,
  `M\u1ed1i li\u00ean h\u1ec7 gi\u1eefa cung ho\u00e0ng \u0111\u1ea1o n\u00e0y v\u00e0 b\u1ea1n,`,
  `R\u00f5 r\u00e0ng n\u00f3 c\u00f3 th\u1ec3 ph\u1ea3n \u00e1nh nhi\u1ec1u n\u00e9t v\u0103n h\u00f3a li\u00ean quan \u0111\u1ebfn ngu\u1ed3n g\u1ed1c c\u1ee7a n\u00f3.`,
  `B\u1ea1n c\u00f3 mu\u1ed1n nghe th\u00eam truy\u1ec7n d\u00e2n gian kh\u00f4ng?`,
  `Qua c\u00e2u chuy\u1ec7n c\u1ee7a ng\u01b0\u1eddi Maya n\u00e0y,`,
  `Khi hai anh em sinh \u0111\u00f4i c\u1ed1 g\u1eafng l\u1eeba d\u1ed1i T\u1eed th\u1ea7n v\u00e0 \u0111i \u0111\u1ebfn th\u1ebf gi\u1edbi ng\u1ea7m Xibalba.`,
  `Ho\u1eb7c, xem video n\u00e0y \u0111\u1ec3 t\u00ecm hi\u1ec3u s\u00e2u h\u01a1n v\u1ec1 th\u1ea7n tho\u1ea1i Nh\u1eadt B\u1ea3n v\u1ec1 Tanuki, m\u1ed9t b\u1eadc th\u1ea7y bi\u1ebfn h\u00ecnh.`,
];

