const JOVANE_MACAU_VLOG_OZ9CEIUFZX0_TRANSLATIONS = [
  `Ch\u00fang ta s\u1ebd kh\u1edfi h\u00e0nh \u0111i Ma Cao,`,
  `H\u1eb9n g\u1eb7p l\u1ea1i \u1edf Ma Cao!`,
  `V\u1eeba \u0111\u1ebfn s\u00e2n bay \u0111\u00e3 c\u00f3 xe \u0111\u01b0a ch\u00fang t\u00f4i v\u1ec1 kh\u00e1ch s\u1ea1n,`,
  `H\u01a1n n\u1eefa, chi\u1ebfc xe n\u00e0y si\u00eau tho\u1ea3i m\u00e1i,`,
  `B\u1ea1n th\u1ea5y kh\u00f4ng, gh\u1ebf ng\u1ed3i c\u00f2n c\u00f3 n\u00fat b\u1ea5m n\u1eefa.`,
  `C\u1ee9 nh\u01b0 v\u1eady l\u00e0 \u0111\u01b0\u1ee3c.`,
  `Tada, t\u00f4i \u0111\u00e3 c\u00f3 Makau Pass r\u1ed3i. G\u00f3i du l\u1ecbch l\u1ea7n n\u00e0y c\u1ee7a ch\u00fang t\u00f4i c\u0169ng bao g\u1ed3m Makau Pass n\u00e0y.`,
  `\u0110\u1ebfn Ma Cao nh\u1ea5t \u0111\u1ecbnh ph\u1ea3i c\u00f3 Makau Pass, v\u00ec Makau Pass n\u00e0y c\u00f3 th\u1ec3 d\u00f9ng \u0111\u1ec3 \u0111i xe bu\u00fdt,`,
  `V\u00e0 mua s\u1eafm. B\u00e2y gi\u1edd ch\u00fang t\u00f4i s\u1ebd \u0111i nh\u1eadn ph\u00f2ng,`,
  `Ch\u00fang t\u00f4i \u0111\u00e3 nh\u1eadn ph\u00f2ng kh\u00e1ch s\u1ea1n r\u1ed3i, b\u00e2y gi\u1edd s\u1ebd d\u1eabn m\u1ecdi ng\u01b0\u1eddi \u0111i tham quan ph\u00f2ng nhanh.`,
  `T\u00f4i \u0111\u00e3 t\u1eafm r\u1eeda xong, t\u00f4i mu\u1ed1n chia s\u1ebb v\u1edbi m\u1ecdi ng\u01b0\u1eddi r\u1eb1ng chuy\u1ebfn \u0111i Ma Cao l\u1ea7n n\u00e0y c\u1ee7a t\u00f4i th\u1ef1c ra l\u00e0 m\u1ed9t g\u00f3i du l\u1ecbch \u0111\u01b0\u1ee3c \u0111\u1eb7t tr\u00ean Touch 'n Go eWallet,`,
  `T\u00ean c\u1ee7a g\u00f3i du l\u1ecbch n\u00e0y l\u00e0 Voyage,`,
  `N\u00f3 bao g\u1ed3m v\u00e9 m\u00e1y bay, ch\u1ed7 \u1edf,`,
  `D\u1ecbch v\u1ee5 \u0111\u01b0a \u0111\u00f3n s\u00e2n bay, v\u00e0 m\u1ed9t s\u1ed1 Voucher, v.v.`,
  `Ngo\u00e0i vi\u1ec7c r\u1ea5t ti\u1ec7n l\u1ee3i, t\u00f4i ngh\u0129 gi\u00e1 c\u1ee7a n\u00f3 c\u0169ng kh\u00e1 ph\u1ea3i ch\u0103ng.`,
  `Trong v\u00e0i ng\u00e0y t\u1edbi, t\u00f4i s\u1ebd c\u00f9ng c\u00e1c b\u1ea1n tr\u1ea3i nghi\u1ec7m g\u00f3i du l\u1ecbch n\u00e0y,`,
  `\u0110\u01b0a c\u00e1c b\u1ea1n \u0111i \u0103n u\u1ed1ng \u1edf Macao.`,
  `B\u00e2y gi\u1edd ch\u00fang ta s\u1ebd ra ngo\u00e0i,`,
  `V\u1eeba nhanh ch\u00f3ng chia s\u1ebb l\u00e0 \u1edf Galaxy Macau Pass n\u00e0y c\u0169ng c\u00f3 th\u1ec3 mua Makau Pass,`,
  `Makau Pass \u1edf \u0111\u00e2y l\u00e0 phi\u00ean b\u1ea3n \u0111\u1eb7c bi\u1ec7t, c\u00e1c b\u1ea1n c\u00f2n c\u00f3 th\u1ec3 tr\u1ef1c ti\u1ebfp n\u1ea1p ti\u1ec1n \u1edf \u0111\u00e2y.`,
  `\u0110\u1ebfn Macao nh\u1ea5t \u0111\u1ecbnh ph\u1ea3i \u0103n m\u00f3n rau \u0111\u1eafng ch\u00ednh hi\u1ec7u.`,
  `\u0110\u00e3 g\u1ecdi m\u1ed9t su\u1ea5t c\u01a1m h\u1ea7m h\u1ea3i s\u1ea3n \u0111\u1eafng,`,
  `V\u00e0 g\u00e0 n\u01b0\u1edbng \u0111\u1eb7c bi\u1ec7t.`,
  `C\u01a1m \u1edf \u0111\u00e2y ngon qu\u00e1,`,
  `H\u1ea3i s\u1ea3n r\u1ea5t t\u01b0\u01a1i.`,
  `Th\u1eadt s\u1ef1 r\u1ea5t ti\u1ec7n l\u1ee3i.`,
  `B\u00e2y gi\u1edd t\u00f4i s\u1ebd l\u1ea5y v\u00e9,`,
  `\u0110\u1ec3 \u0111i xem th\u00e1p Macao.`,
  `Anh \u1ea5y \u0111\u01b0a cho ch\u00fang t\u00f4i.`,
  `H\u1ea3i s\u1ea3n t\u1ef1 ch\u1ecdn c\u1ee7a t\u00f4i,`,
  `C\u1ea3 con h\u00e0u n\u00e0y n\u1eefa. \u1eeam,`,
  `Wow, n\u00f3 th\u1ef1c s\u1ef1 r\u1ea5t t\u01b0\u01a1i.`,
  `C\u1ee9 nh\u01b0 th\u1ec3 t\u00f4i \u0111ang b\u01b0\u1edbc v\u00e0o m\u1ed9t l\u00e2u \u0111\u00e0i, m\u1ed9t th\u1ebf gi\u1edbi c\u1ed5 t\u00edch v\u1eady.`,
  `N\u01a1i n\u00e0y th\u1ef1c s\u1ef1 r\u1ea5t \u0111\u1eb9p.`,
  `Trung t\u00e2m th\u01b0\u01a1ng m\u1ea1i n\u00e0y c\u00f3 r\u1ea5t nhi\u1ec1u ti\u1ec7m b\u00e1nh.`,
  `Nh\u1eefng ti\u1ec7m b\u00e1nh n\u00e0y \u0111\u1ec1u b\u00e1n nh\u1eefng lo\u1ea1i b\u00e1nh quy \u0111\u1ecba ph\u01b0\u01a1ng \u0111\u1eb7c tr\u01b0ng.`,
  `B\u00e2y gi\u1edd t\u00f4i s\u1ebd \u0111i mua v\u00e0i m\u00f3n qu\u00e0 l\u01b0u ni\u1ec7m v\u1ec1 cho gia \u0111\u00ecnh.`,
  `B\u00e1nh g\u00e0, c\u00f2n c\u00f3 ch\u1eef 'c\u1ee5c c\u1ee5c c\u1ee5c c\u1ee5c c\u1ee5c'.`,
  `Ng\u00e0y cu\u1ed1i c\u00f9ng r\u1ed3i, cu\u1ed1i c\u00f9ng c\u0169ng mua \u0111\u01b0\u1ee3c b\u00e1nh tart tr\u1ee9ng m\u00e0 t\u00f4i h\u1eb1ng mong \u01b0\u1edbc.`,
  `\u0110\u00e2y l\u00e0 b\u00e1nh tart tr\u1ee9ng ngon nh\u1ea5t Ma Cao.`,
  `\u01afm, n\u00f3 th\u1ef1c s\u1ef1 r\u1ea5t th\u01a1m.`,
  `Ch\u1ec9 c\u1ea7n mua tr\u00ean \u1ee9ng d\u1ee5ng Touch 'n Go eWallet, \u1edf \u0111\u00e2y c\u00f3 nhi\u1ec1u g\u00f3i kh\u00e1c nhau \u0111\u1ec3 m\u1ecdi ng\u01b0\u1eddi l\u1ef1a ch\u1ecdn \u0111\u00f3.`,
  `\u0110\u01a1n gi\u1ea3n l\u00e0 v\u1eady \u0111\u00f3.`,
  `T\u1ea1m bi\u1ec7t!`,
];

