const TEDED_WILDLIFE_CLIMATE_GYWPFSJ_MBA_TRANSLATIONS = [
  `Nhi\u1ec7t \u0111\u1ed9 v\u00e0 m\u1ef1c n\u01b0\u1edbc bi\u1ec3n ng\u00e0y c\u00e0ng t\u0103ng cao,`,
  `h\u1ea1n h\u00e1n nghi\u00eam tr\u1ecdng,`,
  `\u0111\u1ecba h\u00ecnh thay \u0111\u1ed5i,`,
  `t\u1ea5t c\u1ea3 nh\u1eefng \u0111i\u1ec1u n\u00e0y khi\u1ebfn kh\u1ea3 n\u0103ng th\u00edch \u1ee9ng th\u00e0nh c\u00f4ng v\u1edbi bi\u1ebfn \u0111\u1ed5i kh\u00ed h\u1eadu tr\u1edf n\u00ean quan tr\u1ecdng h\u01a1n bao gi\u1edd h\u1ebft.`,
  `\u0110\u1ed1i v\u1edbi con ng\u01b0\u1eddi ch\u00fang ta, \u0111\u00f3 l\u00e0 vi\u1ec7c s\u1eed d\u1ee5ng c\u00f4ng ngh\u1ec7 ti\u00ean ti\u1ebfn \u0111\u1ec3 t\u00ecm ki\u1ebfm c\u00e1c gi\u1ea3i ph\u00e1p,`,
  `ch\u1eb3ng h\u1ea1n nh\u01b0 c\u00e1c th\u00e0nh ph\u1ed1 th\u00f4ng minh h\u01a1n v\u00e0 qu\u1ea3n l\u00fd t\u00e0i nguy\u00ean n\u01b0\u1edbc t\u1ed1t h\u01a1n.`,
  `Nh\u01b0ng \u0111\u1ed1i v\u1edbi \u0111\u1ed9ng v\u1eadt v\u00e0 th\u1ef1c v\u1eadt,`,
  `\u0111\u1ec3 th\u00edch nghi v\u1edbi nh\u1eefng thay \u0111\u1ed5i n\u00e0y c\u1ea7n c\u00f3 c\u00e1ch th\u1ee9c c\u1ed5 x\u01b0a nh\u1ea5t,`,
  `\u0111\u00f3 l\u00e0 s\u1ef1 ti\u1ebfn h\u00f3a.`,
  `Ti\u1ebfn h\u00f3a th\u01b0\u1eddng m\u1ea5t h\u00e0ng tr\u0103m tri\u1ec7u, th\u1eadm ch\u00ed h\u00e0ng t\u1ef7 n\u0103m,`,
  `nh\u01b0ng trong nh\u1eefng m\u00f4i tr\u01b0\u1eddng lo\u1ea1i b\u1ecf c\u1ef1c k\u1ef3 kh\u1eafc nghi\u1ec7t nh\u01b0 bi\u1ebfn \u0111\u1ed5i kh\u00ed h\u1eadu nhanh ch\u00f3ng,`,
  `c\u00e1c lo\u00e0i \u0111ang ti\u1ebfn h\u00f3a nhanh ch\u00f3ng.`,
  `Trong v\u00e0i th\u1eadp k\u1ef7 g\u1ea7n \u0111\u00e2y, ch\u00fang ta \u0111\u00e3 ch\u1ee9ng ki\u1ebfn nhi\u1ec1u lo\u00e0i th\u1ef1c v\u1eadt,`,
  `\u0111\u1ed9ng v\u1eadt, c\u00f4n tr\u00f9ng di c\u01b0.`,
  `Ch\u00fang \u0111\u00e3 tr\u1ea3i qua nh\u1eefng thay \u0111\u1ed5i v\u1ec1 k\u00edch th\u01b0\u1edbc c\u01a1 th\u1ec3,`,
  `v\u00e0 s\u1ef1 thay \u0111\u1ed5i th\u1eddi gian ra hoa, sinh s\u1ea3n.`,
  `Tuy nhi\u00ean, \u0111\u1ed1i v\u1edbi c\u00e1c \u0111\u1eb7c \u0111i\u1ec3m sinh l\u00fd c\u00e1 th\u1ec3,`,
  `nhi\u1ec1u thay \u0111\u1ed5i c\u00f3 t\u00ednh ch\u1ea5t m\u1ec1m d\u1ebbo,`,
  `ngh\u0129a l\u00e0 nh\u1eefng thay \u0111\u1ed5i kh\u00f4ng th\u1ec3 di truy\u1ec1n.`,
  `H\u01a1n n\u1eefa, kh\u1ea3 n\u0103ng c\u1ee7a m\u1ed9t sinh v\u1eadt \u0111\u1ec3 thay \u0111\u1ed5i ch\u1ee9c n\u0103ng sinh l\u00fd c\u1ee7a m\u00ecnh nh\u1eb1m th\u00edch nghi v\u1edbi y\u00eau c\u1ea7u m\u00f4i tr\u01b0\u1eddng l\u00e0 c\u00f3 h\u1ea1n.`,
  `kh\u1ea3 n\u0103ng thay \u0111\u1ed5i ch\u1ee9c n\u0103ng sinh l\u00fd c\u1ee7a m\u1ed9t sinh v\u1eadt \u0111\u1ec3 th\u00edch nghi v\u1edbi y\u00eau c\u1ea7u m\u00f4i tr\u01b0\u1eddng l\u00e0 c\u00f3 h\u1ea1n.`,
  `\u0110\u00e2y l\u00e0 l\u00fd do t\u1ea1i sao c\u00e1c nh\u00e0 khoa h\u1ecdc \u0111ang t\u00ecm ki\u1ebfm c\u00e1c v\u00ed d\u1ee5 v\u1ec1 qu\u00e1 tr\u00ecnh ti\u1ebfn h\u00f3a trong DNA c\u1ee7a lo\u00e0i.`,
  `Nh\u1eefng thay \u0111\u1ed5i ti\u1ebfn h\u00f3a n\u00e0y c\u00f3 t\u00ednh di truy\u1ec1n,`,
  `l\u00e0 b\u1ec1n v\u1eefng v\u00e0 c\u00f3 \u00fd ngh\u0129a l\u1edbn \u0111\u1ed1i v\u1edbi t\u01b0\u01a1ng lai c\u1ee7a lo\u00e0i.`,
  `L\u1ea5y c\u00fa x\u00e1m l\u00e0m v\u00ed d\u1ee5,`,
  `N\u1ebfu ba m\u01b0\u01a1i n\u0103m tr\u01b0\u1edbc b\u1ea1n \u0111i b\u1ed9 trong khu r\u1eebng l\u1ea1nh gi\u00e1 \u1edf B\u1eafc \u00c2u,`,
  `B\u1ea1n c\u00f3 th\u1ec3 kh\u00f4ng nh\u00ecn th\u1ea5y lo\u00e0i chim kh\u00f3 t\u00ecm n\u00e0y,`,
  `M\u00e0 c\u00f3 th\u1ec3 ch\u1ec9 nghe th\u1ea5y \u00e2m thanh c\u1ee7a ch\u00fang.`,
  `Tr\u00ean n\u1ec1n tuy\u1ebft tr\u1eafng,`,
  `L\u00f4ng c\u1ee7a ch\u00fang kh\u00f3 b\u1ecb ph\u00e1t hi\u1ec7n.`,
  `T\u00ecnh h\u00ecnh ng\u00e0y nay \u0111\u00e3 r\u1ea5t kh\u00e1c.`,
  `T\u1eeb khi bi\u1ebfn \u0111\u1ed5i kh\u00ed h\u1eadu v\u00e0o nh\u1eefng n\u0103m 1980 khi\u1ebfn l\u01b0\u1ee3ng tuy\u1ebft r\u01a1i gi\u1ea3m m\u1ea1nh,`,
  `nh\u01b0ng b\u1ea1n v\u1eabn kh\u00f3 t\u00ecm th\u1ea5y c\u00fa tro, v\u00ec gi\u1edd \u0111\u00e2y ch\u00fang chuy\u1ec3n sang m\u00e0u n\u00e2u.`,
  `Bi\u1ebfn th\u1ec3 m\u00e0u n\u00e2u n\u00e0y l\u00e0 \u0111\u1eb7c \u0111i\u1ec3m tr\u1ed9i c\u1ee7a lo\u00e0i,`,
  `nh\u01b0ng trong l\u1ecbch s\u1eed, \u0111\u1eb7c \u0111i\u1ec3m l\u1eb7n m\u00e0u x\u00e1m nh\u1ea1t l\u1ea1i chi\u1ebfm \u01b0u th\u1ebf.`,
  `Nh\u1edd nh\u1eefng l\u1ee3i th\u1ebf ch\u1ecdn l\u1ecdc \u0111\u1eb7c bi\u1ec7t n\u00e0y,`,
  `nh\u1eefng k\u1ebb s\u0103n m\u1ed3i n\u00e0y c\u00f3 th\u1ec3 h\u00f2a nh\u1eadp v\u00e0o m\u00f4i tr\u01b0\u1eddng.`,
  `Nh\u01b0ng l\u01b0\u1ee3ng tuy\u1ebft r\u01a1i gi\u1ea3m \u0111\u00e3 l\u00e0m gi\u1ea3m hi\u1ec7u qu\u1ea3 ng\u1ee5y trang c\u1ee7a ch\u00fang,`,
  `n\u00ean trong ch\u1ecdn l\u1ecdc t\u1ef1 nhi\u00ean g\u1ea7n \u0111\u00e2y, bi\u1ebfn th\u1ec3 m\u00e0u x\u00e1m thua k\u00e9m h\u01a1n.`,
  `Tuy nhi\u00ean, nh\u1eefng c\u00e1 th\u1ec3 mang bi\u1ebfn th\u1ec3 m\u00e0u n\u00e2u l\u1ea1i c\u00f3 l\u1ee3i th\u1ebf trong c\u00e1c khu r\u1eebng l\u1ed9 thi\u00ean,`,
  `v\u00e0 c\u00fa tro m\u00e0u n\u00e2u ng\u00e0y c\u00e0ng nhi\u1ec1u.`,
  `M\u1ed9t s\u1ed1 lo\u00e0i kh\u00e1c c\u0169ng tr\u1ea3i qua nh\u1eefng bi\u1ebfn \u0111\u1ed5i t\u01b0\u01a1ng t\u1ef1 \u0111\u1ec3 th\u00edch nghi v\u1edbi bi\u1ebfn \u0111\u1ed5i kh\u00ed h\u1eadu trong nh\u1eefng th\u1eadp k\u1ef7 g\u1ea7n \u0111\u00e2y.`,
  `Mu\u1ed7i \u0103n th\u1ecbt \u0111\u00e3 ti\u1ebfn h\u00f3a nhanh ch\u00f3ng,`,
  `ch\u00fang b\u1eaft \u0111\u1ea7u ng\u1ee7 \u0111\u00f4ng mu\u1ed9n h\u01a1n,`,
  `\u0111\u1ec3 t\u1eadn d\u1ee5ng th\u1eddi ti\u1ebft \u1ea5m \u00e1p h\u01a1n.`,
  `Tr\u01b0\u1edbc \u0111\u00e2y c\u00f3 s\u1ed1 l\u01b0\u1ee3ng b\u1ecd r\u00f9a hai ch\u1ea5m lo\u1ea1i \u0111en v\u00e0 kh\u00f4ng \u0111en t\u01b0\u01a1ng \u0111\u01b0\u01a1ng nhau,`,
  `gi\u1edd \u0111\u00e2y ch\u00fang \u0111\u00e3 ho\u00e0n to\u00e0n bi\u1ebfn th\u00e0nh lo\u1ea1i kh\u00f4ng \u0111en.`,
  `C\u00e1c nh\u00e0 khoa h\u1ecdc cho r\u1eb1ng \u0111i\u1ec1u n\u00e0y gi\u00fap ch\u00fang kh\u00f4ng b\u1ecb qu\u00e1 nhi\u1ec7t.`,
  `\u0110\u1ed3ng th\u1eddi, c\u00e1 h\u1ed3i Coho, b\u1eb1ng c\u00e1ch \u0111\u1ebb tr\u1ee9ng s\u1edbm h\u01a1n \u0111\u1ec3 b\u1ea3o v\u1ec7 nh\u1eefng qu\u1ea3 tr\u1ee9ng m\u1ecfng manh c\u1ee7a m\u00ecnh,`,
  `\u0111\u00e3 th\u00edch nghi v\u1edbi v\u00f9ng n\u01b0\u1edbc \u1ea5m h\u01a1n.`,
  `C\u1ecf x\u1ea1 h\u01b0\u01a1ng hoang d\u00e3 \u1edf ch\u00e2u \u00c2u ti\u1ebft ra nhi\u1ec1u d\u1ea7u b\u1ea3o v\u1ec7 h\u01a1n \u0111\u1ec3 ch\u1ed1ng l\u1ea1i s\u1ef1 gia t\u0103ng c\u1ee7a \u0111\u1ed9ng v\u1eadt \u0103n c\u1ecf do th\u1eddi ti\u1ebft \u1ea5m \u00e1p.`,
  `Nh\u1eefng lo\u00e0i n\u00e0y thu\u1ed9c m\u1ed9t qu\u1ea7n th\u1ec3 v\u1edbi hai m\u01b0\u01a1i lo\u00e0i \u0111\u01b0\u1ee3c x\u00e1c \u0111\u1ecbnh.`,
  `Nh\u1eefng lo\u00e0i n\u00e0y bao g\u1ed3m r\u1eafn,`,
  `C\u00e1c lo\u00e0i ti\u1ebfn h\u00f3a \u0111\u1ec3 th\u00edch nghi v\u1edbi bi\u1ebfn \u0111\u1ed5i kh\u00ed h\u1eadu, bao g\u1ed3m r\u00f9a c\u00e1 s\u1ea5u,`,
  `nh\u01b0 \u1ebfch g\u1ed7, c\u00e2y h\u1ecd c\u00fac v\u00e0 b\u01b0\u1edbm b\u1ea1c \u0111\u1ed1m.`,
  `Tuy nhi\u00ean, c\u00e1c nh\u00e0 khoa h\u1ecdc hy v\u1ecdng trong s\u1ed1 87 tri\u1ec7u lo\u00e0i tr\u00ean Tr\u00e1i \u0110\u1ea5t,`,
  `s\u1ebd t\u00ecm th\u1ea5y nhi\u1ec1u lo\u00e0i h\u01a1n \u0111\u00e3 ti\u1ebfn h\u00f3a \u0111\u1ec3 th\u00edch nghi v\u1edbi bi\u1ebfn \u0111\u1ed5i kh\u00ed h\u1eadu.`,
  `B\u1edfi v\u00ec \u0111\u1ed1i v\u1edbi s\u1ef1 \u0111a d\u1ea1ng sinh h\u1ecdc qu\u00fd gi\u00e1 v\u00e0 \u0111\u00e1ng kinh ng\u1ea1c tr\u00ean h\u00e0nh tinh c\u1ee7a ch\u00fang ta,`,
  `ti\u1ebfn h\u00f3a kh\u00f4ng ph\u1ea3i l\u00e0 c\u00e2u tr\u1ea3 l\u1eddi cu\u1ed1i c\u00f9ng.`,
  `Ng\u01b0\u1ee3c l\u1ea1i, nhi\u1ec1u lo\u00e0i c\u1ea7n ch\u00fang ta gi\u00fap \u0111\u1ee1 \u0111\u1ec3 t\u1ed3n t\u1ea1i trong m\u1ed9t th\u1ebf gi\u1edbi \u0111ang thay \u0111\u1ed5i,`,
  `N\u1ebfu kh\u00f4ng, ch\u00fang s\u1ebd di\u1ec7t vong.`,
  `Tin t\u1ed1t l\u00e0 ch\u00fang ta \u0111\u00e3 c\u00f3 m\u1ed9t s\u1ed1 c\u00f4ng c\u1ee5,`,
  `tr\u00ean to\u00e0n c\u1ea7u, ch\u00fang ta \u0111\u00e3 \u0111\u01b0a ra m\u1ed9t s\u1ed1 quy\u1ebft \u0111\u1ecbnh th\u1ef1c s\u1ef1.`,
  `Nh\u1eefng quy\u1ebft \u0111\u1ecbnh \u0111\u00f3 s\u1ebd gi\u00fap to\u00e0n b\u1ed9 h\u1ec7 sinh th\u00e1i th\u00edch nghi v\u1edbi nh\u1eefng ng\u01b0\u1eddi t\u1ecb n\u1ea1n do bi\u1ebfn \u0111\u1ed5i kh\u00ed h\u1eadu \u0111ang \u0111\u01b0\u1ee3c x\u00e1c \u0111\u1ecbnh v\u00e0 b\u1ea3o v\u1ec7.`,
  `C\u00e1c k\u1ebf ho\u1ea1ch gi\u00fap c\u00e1c lo\u00e0i di c\u01b0 \u0111ang \u0111\u01b0\u1ee3c ti\u1ebfn h\u00e0nh,`,
  `ch\u00fang c\u00f3 th\u1ec3 di chuy\u1ec3n \u0111\u1ebfn m\u00f4i tr\u01b0\u1eddng kh\u00ed h\u1eadu ph\u00f9 h\u1ee3p h\u01a1n.`,
  `C\u00e1c c\u00f4ng vi\u00ean v\u00e0 khu b\u1ea3o t\u1ed3n hi\u1ec7n c\u00f3 \u0111ang ti\u1ebfn h\u00e0nh \u0111i\u1ec1u tra bi\u1ebfn \u0111\u1ed5i kh\u00ed h\u1eadu \u0111\u1ec3 gi\u00fap \u0111\u1ed9ng v\u1eadt hoang d\u00e3 th\u00edch nghi.`,
  `May m\u1eafn thay, t\u1ea5t c\u1ea3 nh\u1eefng \u0111i\u1ec1u n\u00e0y v\u1eabn n\u1eb1m trong t\u1ea7m ki\u1ec3m so\u00e1t c\u1ee7a ch\u00fang ta.`,
  `Ch\u00fang ta v\u1eabn c\u00f3 th\u1ec3 b\u1ea3o v\u1ec7 s\u1ef1 \u0111a d\u1ea1ng sinh h\u1ecdc k\u1ef3 l\u1ea1 tr\u00ean h\u00e0nh tinh n\u00e0y,`,
  `sau c\u00f9ng, ch\u00fang \u0111ang h\u1ed7 tr\u1ee3 s\u1ef1 s\u1ed1ng c\u00f2n c\u1ee7a lo\u00e0i ng\u01b0\u1eddi ch\u00fang ta b\u1eb1ng nhi\u1ec1u c\u00e1ch kh\u00e1c nhau.`,
  `B\u1ea3o v\u1ec7 v\u00e0 b\u1ea3o t\u1ed3n thi\u00ean nhi\u00ean c\u1ee7a ch\u00fang ta c\u1ea7n tr\u1edf th\u00e0nh \u01b0u ti\u00ean h\u00e0ng \u0111\u1ea7u c\u1ee7a m\u1ecdi qu\u1ed1c gia,`,
  `c\u00f4ng ty v\u00e0 c\u1ed9ng \u0111\u1ed3ng tr\u00ean th\u1ebf gi\u1edbi.`,
  `N\u1ebfu b\u1ea1n mu\u1ed1n bi\u1ebft b\u1ea1n c\u00f3 th\u1ec3 th\u1ef1c hi\u1ec7n nh\u1eefng bi\u1ec7n ph\u00e1p c\u1ee5 th\u1ec3 n\u00e0o ngay b\u00e2y gi\u1edd \u0111\u1ec3 gi\u00fap \u0111\u1ea1t \u0111\u01b0\u1ee3c m\u1ee5c ti\u00eau n\u00e0y,`,
  `vui l\u00f2ng truy c\u1eadp eddoted.com/earthgoal.`,
];

