const TEDED_ECONOMY_GROWTH_JVX2WVWB_SG_TRANSLATIONS = [
  `Gi\u1ea3 s\u1eed b\u1ea1n t\u00ecm th\u1ea5y m\u1ed9t \u0111\u1ed3ng xu th\u1ea7n k\u1ef3,`,
  `c\u1ee9 sau m\u1ed7i 25 n\u0103m n\u00f3 l\u1ea1i nh\u00e2n \u0111\u00f4i m\u1ed9t l\u1ea7n.`,
  `Sau 75 n\u0103m, b\u1ea1n s\u1ebd ch\u1ec9 c\u00f3 8 \u0111\u1ed3ng ti\u1ec1n v\u00e0ng.`,
  `Nh\u01b0ng sau 1000 n\u0103m, t\u00e0i s\u1ea3n c\u1ee7a b\u1ea1n s\u1ebd v\u01b0\u1ee3t qu\u00e1 1 ngh\u00ecn t\u1ef7.`,
  `Ch\u1ec9 c\u1ea7n 4600 n\u0103m, s\u1ed1 ti\u1ec1n v\u00e0ng c\u1ee7a b\u1ea1n s\u1ebd v\u01b0\u1ee3t qu\u00e1 v\u0169 tr\u1ee5 c\u00f3 th\u1ec3 quan s\u00e1t \u0111\u01b0\u1ee3c.`,
  `Vi\u1ec7c nh\u00e2n \u0111\u00f4i \u0111\u1ecbnh k\u1ef3 n\u00e0y l\u00e0 m\u1ed9t v\u00ed d\u1ee5 v\u1ec1 t\u0103ng tr\u01b0\u1edfng theo c\u1ea5p s\u1ed1 nh\u00e2n.`,
  `M\u1eb7c d\u00f9 trong th\u1ef1c t\u1ebf ch\u00fang ta kh\u00f4ng t\u00ecm th\u1ea5y lo\u1ea1i \u201c\u0111\u1ed3ng ti\u1ec1n ma thu\u1eadt\u201d n\u00e0o c\u00f3 m\u1ee9c \u0111\u1ed9 r\u1ee7i ro k\u1ef3 di\u1ec7u v\u00e0 h\u1ea5p d\u1eabn nh\u01b0 v\u1eady,`,
  `nh\u01b0ng trong 200 n\u0103m qua c\u00f3 m\u1ed9t th\u1ee9 g\u1ea7n nh\u01b0 quan tr\u1ecdng kh\u00f4ng k\u00e9m:`,
  `S\u1ef1 b\u00f9ng n\u1ed5 c\u1ee7a n\u1ec1n kinh t\u1ebf to\u00e0n c\u1ea7u.`,
  `Nhi\u1ec1u nh\u00e0 kinh t\u1ebf cho r\u1eb1ng,`,
  `t\u0103ng tr\u01b0\u1edfng kinh t\u1ebf b\u1ec1n v\u1eefng l\u00e0 c\u1ea7n thi\u1ebft \u0111\u1ec3 duy tr\u00ec s\u1ef1 c\u1ea3i thi\u1ec7n li\u00ean t\u1ee5c trong \u0111\u1eddi s\u1ed1ng c\u1ee7a con ng\u01b0\u1eddi.`,
  `N\u1ebfu n\u1ec1n kinh t\u1ebf to\u00e0n c\u1ea7u ng\u1eebng t\u0103ng tr\u01b0\u1edfng,`,
  `m\u1ecdi ng\u01b0\u1eddi s\u1ebd tranh gi\u00e0nh nh\u1eefng gi\u00e1 tr\u1ecb c\u1ed1 \u0111\u1ecbnh hi\u1ec7n c\u00f3,`,
  `thay v\u00ec t\u1ea1o ra nh\u1eefng gi\u00e1 tr\u1ecb m\u1edbi.`,
  `V\u1eady v\u1ea5n \u0111\u1ec1 l\u00e0 \u0111\u00e2y:`,
  `V\u1edbi t\u00e0i nguy\u00ean h\u00e0nh tinh c\u00f3 h\u1ea1n,`,
  `li\u1ec7u t\u0103ng tr\u01b0\u1edfng kinh t\u1ebf v\u00f4 h\u1ea1n c\u00f3 th\u1ec3 \u0111\u1ea1t \u0111\u01b0\u1ee3c kh\u00f4ng?`,
  `Ch\u00fang ta \u0111o l\u01b0\u1eddng t\u0103ng tr\u01b0\u1edfng kinh t\u1ebf b\u1eb1ng c\u00e1ch theo d\u00f5i t\u1ed5ng gi\u00e1 tr\u1ecb h\u00e0ng h\u00f3a`,
  `\u0111\u01b0\u1ee3c s\u1ea3n xu\u1ea5t v\u00e0 b\u00e1n ra c\u1ee7a m\u1ed9t qu\u1ed1c gia ho\u1eb7c to\u00e0n th\u1ebf gi\u1edbi.`,
  `Nh\u1eefng s\u1ea3n ph\u1ea9m n\u00e0y c\u00f3 th\u1ec3 \u0111\u00e1p \u1ee9ng nhu c\u1ea7u c\u01a1 b\u1ea3n c\u1ee7a ch\u00fang ta`,
  `v\u00e0 c\u0169ng n\u00e2ng cao ch\u1ea5t l\u01b0\u1ee3ng cu\u1ed9c s\u1ed1ng c\u00e1 nh\u00e2n v\u00e0 t\u1eadp th\u1ec3.`,
  `\u0110i\u1ec1u quan tr\u1ecdng l\u00e0 vi\u1ec7c ph\u00e1t minh,`,
  `ch\u1ebf t\u1ea1o, v\u00e0 th\u1eadm ch\u00ed duy tr\u00ec hi\u1ec7n tr\u1ea1ng \u0111\u1ec1u ti\u00eau t\u1ed1n t\u00e0i nguy\u00ean.`,
  `V\u00ed d\u1ee5, \u0111i\u1ec7n tho\u1ea1i th\u00f4ng minh.`,
  `M\u1ed9t ph\u1ea7n gi\u00e1 tr\u1ecb c\u1ee7a n\u00f3 \u0111\u1ebfn t\u1eeb nh\u00f4m,`,
  `gali v\u00e0 silic c\u00f3 trong \u0111\u00f3, nh\u1eefng th\u1ee9 n\u00e0y \u0111\u00f2i h\u1ecfi khai th\u00e1c v\u00e0 tinh ch\u1ebf n\u0103ng l\u01b0\u1ee3ng v\u00e0 t\u00e0i nguy\u00ean,`,
  `tr\u01b0\u1edbc khi c\u00f3 th\u1ec3 ch\u1ebf t\u1ea1o \u0111i\u1ec7n tho\u1ea1i.`,
  `N\u00f3 c\u0169ng c\u00f3 gi\u00e1 tr\u1ecb nh\u1edd v\u00e0o ngu\u1ed3n l\u1ef1c con ng\u01b0\u1eddi tham gia v\u00e0o ph\u1ea7n c\u1ee9ng v\u00e0 vi\u1ebft ph\u1ea7n m\u1ec1m.`,
  `T\u1ea5t nhi\u00ean, gi\u00e1 tr\u1ecb c\u1ee7a n\u00f3 c\u00f2n \u0111\u01b0\u1ee3c th\u1ec3 hi\u1ec7n qua vi\u1ec7c m\u1ed9t ng\u01b0\u1eddi \u0111\u00e0n \u00f4ng m\u1eb7c \u00e1o c\u1ed5 l\u1ecd m\u00e0u \u0111en tr\u00ean s\u00e2n kh\u1ea5u n\u00f3i v\u1edbi b\u1ea1n r\u1eb1ng n\u00f3 qu\u00fd gi\u00e1 \u0111\u1ebfn m\u1ee9c n\u00e0o.`,
  `V\u1eady, l\u00e0m th\u1ebf n\u00e0o ch\u00fang ta c\u00f3 th\u1ec3 t\u0103ng t\u1ed5ng gi\u00e1 tr\u1ecb t\u00e0i ch\u00ednh c\u1ee7a m\u1ecdi th\u1ee9?`,
  `M\u1ed9t c\u00e1ch l\u00e0 s\u1ea3n xu\u1ea5t nhi\u1ec1u h\u01a1n,`,
  `c\u00e1ch kh\u00e1c l\u00e0 ph\u00e1t minh ra c\u00e1i m\u1edbi.`,
  `D\u00f9 b\u1ea1n l\u00e0m th\u1ebf n\u00e0o,`,
  `t\u0103ng tr\u01b0\u1edfng kinh t\u1ebf \u0111\u1ec1u c\u1ea7n s\u1ef1 h\u1ed7 tr\u1ee3 c\u1ee7a t\u00e0i nguy\u00ean v\u00e0 n\u0103ng l\u01b0\u1ee3ng.`,
  `Cu\u1ed1i c\u00f9ng, ch\u00fang ta c\u00f3 ti\u00eau th\u1ee5 h\u1ebft ch\u00fang kh\u00f4ng?`,
  `\u0110\u1ec3 tr\u1ea3 l\u1eddi c\u00e2u h\u1ecfi n\u00e0y,`,
  `h\u00e3y xem x\u00e9t nh\u1eefng nguy\u00ean li\u1ec7u m\u00e0 n\u1ec1n kinh t\u1ebf c\u1ea7n l\u00e0 g\u00ec.`,
  `V\u00e0 n\u1ec1n kinh t\u1ebf \u0111\u00e3 s\u1ea3n xu\u1ea5t ra g\u00ec?`,
  `N\u00f3 c\u1ea7n lao \u0111\u1ed9ng,`,
  `v\u1ed1n, hay n\u00f3i c\u00e1ch kh\u00e1c l\u00e0 ti\u1ec1n,`,
  `c\u0169ng nh\u01b0 t\u00e0i nguy\u00ean thi\u00ean nhi\u00ean,`,
  `v\u00ed d\u1ee5 nh\u01b0 n\u01b0\u1edbc ho\u1eb7c n\u0103ng l\u01b0\u1ee3ng.`,
  `Sau \u0111\u00f3, n\u00f3 t\u1ea1o ra gi\u00e1 tr\u1ecb.`,
  `Trong 200 n\u0103m qua,`,
  `c\u00e1c n\u1ec1n kinh t\u1ebf \u0111\u00e3 t\u0103ng hi\u1ec7u qu\u1ea3 t\u1ea1o ra gi\u00e1 tr\u1ecb theo c\u1ea5p s\u1ed1 nh\u00e2n.`,
  `N\u1ebfu ch\u00fang ta, v\u1edbi t\u01b0 c\u00e1ch l\u00e0 m\u1ed9t gi\u1ed1ng lo\u00e0i,`,
  `c\u00f3 th\u1ec3 kh\u00f4ng ng\u1eebng ph\u00e1t tri\u1ec3n kinh t\u1ebf c\u1ee7a m\u00ecnh,`,
  `v\u00e0 l\u00e0m cho n\u00f3 t\u1ea1o ra nhi\u1ec1u l\u1ee3i \u00edch h\u01a1n,`,
  `v\u1ec1 l\u00fd thuy\u1ebft,`,
  `ch\u00fang ta c\u00f3 th\u1ec3 s\u1eed d\u1ee5ng c\u00f9ng m\u1ed9t l\u01b0\u1ee3ng,`,
  `ho\u1eb7c tham v\u1ecdng h\u01a1n m\u1ed9t ch\u00fat,`,
  `s\u1eed d\u1ee5ng \u00edt t\u00e0i nguy\u00ean h\u01a1n,`,
  `\u0111\u1ec3 t\u1ea1o ra nhi\u1ec1u gi\u00e1 tr\u1ecb h\u01a1n.`,
  `V\u1eady, ch\u00fang ta n\u00ean l\u00e0m th\u1ebf n\u00e0o?`,
  `Ch\u00fang ta n\u00ean n\u00e2ng cao hi\u1ec7u qu\u1ea3 nh\u01b0 th\u1ebf n\u00e0o?`,
  `B\u1eb1ng c\u00f4ng ngh\u1ec7 m\u1edbi. \u0110\u00e2y l\u00e0 v\u1ea5n \u0111\u1ec1.`,
  `Ngo\u00e0i vi\u1ec7c n\u00e2ng cao hi\u1ec7u qu\u1ea3, c\u00f4ng ngh\u1ec7 m\u1edbi c\u00f2n t\u1ea1o ra nhu c\u1ea7u m\u1edbi,`,
  `v\u00e0 cu\u1ed1i c\u00f9ng s\u1ebd ti\u00eau th\u1ee5 nhi\u1ec1u t\u00e0i nguy\u00ean h\u01a1n.`,
  `Th\u1ef1c t\u1ebf, ch\u00fang ta kh\u00f4ng ph\u1ea3i \u0111\u1ed1i m\u1eb7t v\u1edbi nguy c\u01a1 c\u1ea1n ki\u1ec7t h\u1ea7u h\u1ebft t\u00e0i nguy\u00ean m\u1ed9t c\u00e1ch c\u1ea5p b\u00e1ch.`,
  `Khi ch\u00fang ta c\u00f3 m\u1ed9t v\u1ea5n \u0111\u1ec1 l\u1edbn h\u01a1n v\u00e0 c\u1ea5p b\u00e1ch h\u01a1n,`,
  `N\u1ec1n kinh t\u1ebf to\u00e0n c\u1ea7u, \u0111\u1eb7c bi\u1ec7t t\u1ea1i c\u00e1c qu\u1ed1c gia gi\u00e0u c\u00f3,`,
  `\u0111ang th\u00fac \u0111\u1ea9y bi\u1ebfn \u0111\u1ed5i kh\u00ed h\u1eadu,`,
  `ph\u00e1 h\u1ee7y m\u00f4i tr\u01b0\u1eddng qu\u00fd gi\u00e1 m\u00e0 t\u1ea5t c\u1ea3 ch\u00fang ta ph\u1ee5 thu\u1ed9c v\u00e0o \u2013 \u0111\u1ea5t \u0111ai,`,
  `r\u1eebng, ngh\u1ec1 c\u00e1 v\u00e0 v\u00f4 s\u1ed1 t\u00e0i nguy\u00ean kh\u00e1c gi\u00fap duy tr\u00ec n\u1ec1n v\u0103n minh c\u1ee7a ch\u00fang ta ho\u1ea1t \u0111\u1ed9ng.`,
  `Ch\u00fang ta n\u00ean l\u00e0m g\u00ec?`,
  `\u0110\u00e2y l\u00e0 \u0111i\u1ec1u m\u00e0 c\u00e1c nh\u00e0 kinh t\u1ebf \u0111ang tranh c\u00e3i.`,
  `H\u1ea7u h\u1ebft c\u00e1c nh\u00e0 kinh t\u1ebf \u0111\u1ec1u tin r\u1eb1ng,`,
  `nh\u1eefng \u00fd t\u01b0\u1edfng m\u1edbi s\u1ebd c\u00f3 th\u1ec3 gi\u1ea3i quy\u1ebft h\u1ea7u h\u1ebft c\u00e1c v\u1ea5n \u0111\u1ec1.`,
  `H\u1ecd cho r\u1eb1ng, vi\u1ec7c s\u1eed d\u1ee5ng n\u0103ng l\u01b0\u1ee3ng t\u0103ng theo c\u1ea5p s\u1ed1 nh\u00e2n,`,
  `c\u0169ng \u0111\u00e3 th\u00fac \u0111\u1ea9y t\u0103ng tr\u01b0\u1edfng \u0111\u00e1ng k\u1ec3,`,
  `s\u1ef1 s\u00e1ng t\u1ea1o c\u1ee7a con ng\u01b0\u1eddi c\u0169ng t\u0103ng theo c\u1ea5p s\u1ed1 nh\u00e2n,`,
  `v\u00e0 s\u1ebd \u0111\u1ed1i ph\u00f3 v\u1edbi nh\u1eefng th\u00e1ch th\u1ee9c n\u00e0y theo nh\u1eefng c\u00e1ch m\u00e0 ch\u00fang ta kh\u00f4ng th\u1ec3 l\u01b0\u1eddng tr\u01b0\u1edbc \u0111\u01b0\u1ee3c.`,
  `V\u00ed d\u1ee5, t\u1eeb n\u0103m 2000 \u0111\u1ebfn 2014,`,
  `GDP c\u1ee7a \u0110\u1ee9c t\u0103ng 16%, \u0111\u1ed3ng th\u1eddi gi\u1ea3m 12% l\u01b0\u1ee3ng kh\u00ed th\u1ea3i carbon dioxide.`,
  `\u0110i\u1ec1u n\u00e0y r\u1ea5t \u1ea5n t\u01b0\u1ee3ng,`,
  `Nh\u01b0ng t\u1ed1c \u0111\u1ed9 gi\u1ea3m ph\u00e1t th\u1ea3i c\u1ee7a n\u00f3 v\u1eabn ch\u01b0a \u0111\u1ee7 \u0111\u1ec3 gi\u1edbi h\u1ea1n nhi\u1ec7t \u0111\u1ed9 t\u0103ng \u1edf m\u1ee9c 1,5 \u0111\u1ed9 C.`,
  `V\u00ec nhi\u1ec1u l\u00fd do kh\u00e1c nhau, m\u1ed9t s\u1ed1 nh\u00e0 kinh t\u1ebf cho r\u1eb1ng ch\u00fang ta n\u00ean thay \u0111\u1ed5i ho\u00e0n to\u00e0n c\u01a1 c\u1ea5u kinh t\u1ebf v\u00e0 m\u1ee9c ti\u00eau th\u1ee5 n\u0103ng l\u01b0\u1ee3ng hi\u1ec7n c\u00f3.`,
  `H\u1ecd cho r\u1eb1ng nh\u1eefng g\u00ec ch\u00fang ta th\u1ef1c s\u1ef1 n\u00ean l\u00e0m l\u00e0 lo\u1ea1i b\u1ecf s\u1ef1 ph\u1ee5 thu\u1ed9c v\u00e0o t\u0103ng tr\u01b0\u1edfng,`,
  `v\u00e0 chuy\u1ec3n sang n\u1ec1n kinh t\u1ebf h\u1eadu t\u0103ng tr\u01b0\u1edfng.`,
  `\u0110i\u1ec1u \u0111\u00f3 s\u1ebd nh\u01b0 th\u1ebf n\u00e0o?`,
  `N\u1ec1n kinh t\u1ebf h\u1eadu t\u0103ng tr\u01b0\u1edfng s\u1ebd kh\u00f4ng l\u1ea5y`,
  `Ng\u01b0\u1ee3c l\u1ea1i, n\u00f3 \u0111\u00f2i h\u1ecfi ch\u00fang ta ph\u1ea3i t\u1eadp trung v\u00e0o vi\u1ec7c c\u1ea3i thi\u1ec7n nh\u1eefng th\u1ee9 ch\u00fang ta th\u1ef1c s\u1ef1 c\u1ea7n,`,
  `ch\u1eb3ng h\u1ea1n nh\u01b0 n\u0103ng l\u01b0\u1ee3ng t\u00e1i t\u1ea1o,`,
  `ch\u0103m s\u00f3c s\u1ee9c kh\u1ecfe v\u00e0 giao th\u00f4ng c\u00f4ng c\u1ed9ng.`,
  `\u0110\u1ec3 l\u00e0m \u0111\u01b0\u1ee3c \u0111i\u1ec1u n\u00e0y,`,
  `c\u00e1c nh\u00e0 kinh t\u1ebf h\u1ecdc h\u1eadu t\u0103ng tr\u01b0\u1edfng khuy\u1ebfn ngh\u1ecb c\u00e1c n\u01b0\u1edbc gi\u00e0u n\u00ean th\u1ef1c hi\u1ec7n c\u00e1c bi\u1ec7n ph\u00e1p,`,
  `ch\u1eb3ng h\u1ea1n nh\u01b0 \u0111\u1ea3m b\u1ea3o m\u1ee9c l\u01b0\u01a1ng t\u1ed1i thi\u1ec3u \u0111\u1ec3 s\u1ed1ng,`,
  `th\u00fac \u0111\u1ea9y b\u00ecnh \u0111\u1eb3ng v\u1ec1 c\u1ee7a c\u1ea3i v\u00e0 thu nh\u1eadp,`,
  `v\u00e0 \u0111\u1ea3m b\u1ea3o ph\u1ed5 c\u1eadp c\u00e1c d\u1ecbch v\u1ee5 c\u00f4ng nh\u01b0 y t\u1ebf.`,
  `Trong m\u1ed9t n\u1ec1n kinh t\u1ebf v\u1eadn h\u00e0nh nh\u01b0 v\u1eady,`,
  `Theo l\u00fd thuy\u1ebft,`,
  `m\u1ecdi ng\u01b0\u1eddi s\u1ebd kh\u00f4ng c\u00f2n ph\u1ee5 thu\u1ed9c nhi\u1ec1u v\u00e0o c\u00f4ng vi\u1ec7c \u0111\u1ec3 ki\u1ebfm s\u1ed1ng ho\u1eb7c \u0111\u1ec3 \u0111\u01b0\u1ee3c ch\u0103m s\u00f3c y t\u1ebf,`,
  `do \u0111\u00f3 vi\u1ec7c gi\u1ea3m s\u1ea3n xu\u1ea5t nh\u1eefng s\u1ea3n ph\u1ea9m \u0111\u01b0\u1ee3c cho l\u00e0 \u00edt c\u1ea7n thi\u1ebft h\u01a1n s\u1ebd kh\u1ea3 thi h\u01a1n.`,
  `Nh\u01b0ng \u0111i\u1ec1u n\u00e0y \u0111\u1eb7t ra nh\u1eefng c\u00e2u h\u1ecfi kh\u00e1c:`,
  `Ai s\u1ebd \u0111\u1ecbnh ngh\u0129a c\u00e1i g\u00ec l\u00e0 c\u1ea7n thi\u1ebft?`,
  `L\u00e0m th\u1ebf n\u00e0o ch\u00fang ta c\u00f3 th\u1ec3 gi\u1ea3i quy\u1ebft nh\u1eefng b\u1ea5t \u0111\u1ed3ng kh\u00f4ng th\u1ec3 tr\u00e1nh kh\u1ecfi?`,
  `Ch\u00fang ta c\u00f3 th\u1ec3 tho\u00e1t kh\u1ecfi t\u1ea5t c\u1ea3 c\u00e1c ng\u00e0nh c\u00f4ng nghi\u1ec7p kh\u00f4ng?`,
  `Ch\u00fang ta s\u1ebd c\u00f3 nh\u1eefng quy t\u1eafc m\u1edbi \u0111\u1ec3 gi\u1ea3i quy\u1ebft c\u00e1c d\u1ef1 lu\u1eadt v\u1ec1 nh\u1eefng v\u1ea5n \u0111\u1ec1 hi\u1ec7n c\u00f3,`,
  `c\u00f3 v\u1ebb phi th\u1ef1c t\u1ebf nh\u01b0 \u0111\u1ed3ng v\u00e0ng ph\u00e9p thu\u1eadt v\u1eady.`,
  `V\u00e0 \u0111\u1ec1 xu\u1ea5t r\u1eb1ng ch\u00fang ta ph\u1ea3i thay \u0111\u1ed5i c\u01a1 b\u1ea3n n\u1ec1n kinh t\u1ebf c\u1ee7a m\u00ecnh,`,
  `tr\u00ean ph\u01b0\u01a1ng di\u1ec7n ch\u00ednh tr\u1ecb c\u00f3 v\u1ebb \u0111\u00e1ng s\u1ee3,`,
  `\u0111\u1eb7c bi\u1ec7t l\u00e0 \u1edf c\u00e1c n\u01b0\u1edbc gi\u00e0u c\u00f3.`,
  `D\u00f9 sao \u0111i n\u1eefa, ch\u00fang ta ph\u1ea3i t\u00ecm ra m\u1ed9t c\u00e1ch v\u1eeba c\u00f3 l\u1ee3i cho t\u1ea5t c\u1ea3 m\u1ecdi ng\u01b0\u1eddi,`,
  `v\u1eeba b\u1ea3o v\u1ec7 h\u00e0nh tinh c\u1ee7a ch\u00fang ta.`,
  `Cam k\u1ebft cung c\u1ea5p n\u1ed9i dung gi\u00e1o d\u1ee5c ch\u1ea5t l\u01b0\u1ee3ng cao mi\u1ec5n ph\u00ed cho nhi\u1ec1u ng\u01b0\u1eddi h\u01a1n b\u1eb1ng nhi\u1ec1u ng\u00f4n ng\u1eef.`,
  `H\u00e3y gi\u00fap ch\u00fang t\u00f4i th\u1ef1c hi\u1ec7n s\u1ee9 m\u1ec7nh phi l\u1ee3i nhu\u1eadn b\u1eb1ng c\u00e1ch \u0111\u00f3ng g\u00f3p cho Patreon c\u1ee7a ch\u00fang t\u00f4i,`,
  `v\u00e0 \u0111\u1eebng qu\u00ean \u0111\u0103ng k\u00fd k\u00eanh n\u00e0y.`,
];

