const TEDED_EARTH_WATER_RWEKN3P1VIS_TRANSLATIONS = [
  `N\u00f3 kh\u00f4ng c\u00f3 v\u1ecb,`,
  `m\u00e0u s\u1eafc hay b\u1ea5t k\u1ef3 m\u00f9i n\u00e0o,`,
  `v\u00e0 trong su\u1ed1t. N\u00f3 bao ph\u1ee7 70% b\u1ec1 m\u1eb7t Tr\u00e1i \u0110\u1ea5t,`,
  `lu\u00e2n chuy\u1ec3n qua \u0111\u1ea1i d\u01b0\u01a1ng, s\u00f4ng ng\u00f2i \u0111\u1ebfn nh\u1eefng \u0111\u00e1m m\u00e2y,`,
  `r\u1ed3i tu\u1ea7n ho\u00e0n tr\u1edf l\u1ea1i. Th\u1eadm ch\u00ed n\u00f3 chi\u1ebfm 60% th\u00e0nh ph\u1ea7n c\u01a1 th\u1ec3 ch\u00fang ta.`,
  `V\u00ec c\u00f3 qu\u00e1 nhi\u1ec1u n\u01b0\u1edbc xung quanh v\u00e0 b\u00ean trong ch\u00fang ta,`,
  `ch\u00fang ta coi s\u1ef1 hi\u1ec7n di\u1ec7n c\u1ee7a n\u01b0\u1edbc l\u00e0 \u0111i\u1ec1u hi\u1ec3n nhi\u00ean.`,
  `Nh\u01b0ng \u1edf nh\u1eefng n\u01a1i kh\u00e1c trong h\u1ec7 m\u1eb7t tr\u1eddi,`,
  `h\u1ea7u nh\u01b0 kh\u00f4ng t\u00ecm th\u1ea5y n\u01b0\u1edbc \u1edf d\u1ea1ng l\u1ecfng.`,
  `V\u1eady h\u00e0nh tinh c\u1ee7a ch\u00fang ta l\u00e0m th\u1ebf n\u00e0o m\u00e0 c\u00f3 \u0111\u01b0\u1ee3c nhi\u1ec1u v\u1eadt ch\u1ea5t n\u00e0y \u0111\u1ebfn th\u1ebf,`,
  `r\u1ed1t cu\u1ed9c n\u00f3 \u0111\u1ebfn t\u1eeb \u0111\u00e2u?`,
  `Nh\u01b0 b\u1ea1n c\u00f3 th\u1ec3 \u0111\u00e3 bi\u1ebft,`,
  `m\u1ed9t ph\u00e2n t\u1eed n\u01b0\u1edbc \u0111\u01b0\u1ee3c c\u1ea5u t\u1ea1o t\u1eeb hai th\u00e0nh ph\u1ea7n c\u01a1 b\u1ea3n:`,
  `nguy\u00ean t\u1eed hydro, nguy\u00ean t\u1ed1 \u0111\u01a1n gi\u1ea3n nh\u1ea5t trong t\u1ea5t c\u1ea3 c\u00e1c nguy\u00ean t\u1ed1,`,
  `\u0111\u00e3 c\u00f3 t\u1eeb khi v\u0169 tr\u1ee5 h\u00ecnh th\u00e0nh.`,
  `Nh\u1eefng nguy\u00ean t\u1eed oxy xu\u1ea5t hi\u1ec7n sau h\u00e0ng tr\u0103m tri\u1ec7u n\u0103m k\u1ec3 t\u1eeb khi c\u00e1c h\u00e0nh tinh b\u1eaft \u0111\u1ea7u h\u00ecnh th\u00e0nh.`,
  `Trong nh\u1eefng trung t\u00e2m n\u00f3ng nh\u01b0 \u0111\u1ecba ng\u1ee5c n\u00e0y, \u00e1p l\u1ef1c r\u1ea5t l\u1edbn,`,
  `khi\u1ebfn c\u00e1c nguy\u00ean t\u1eed hydro h\u1ee3p nh\u1ea5t t\u1ea1o ra nguy\u00ean t\u1eed heli.`,
  `C\u00e1c nguy\u00ean t\u1eed heli sau \u0111\u00f3 h\u1ee3p nh\u1ea5t t\u1ea1o ra c\u00e1c nguy\u00ean t\u1eed n\u1eb7ng kh\u00e1c,`,
  `nh\u01b0 beryllium, carbon v\u00e0 oxy,`,
  `qu\u00e1 tr\u00ecnh n\u00e0y \u0111\u01b0\u1ee3c g\u1ecdi l\u00e0 t\u1ed5ng h\u1ee3p h\u1ea1t nh\u00e2n.`,
  `Khi c\u00e1c ng\u00f4i sao cu\u1ed1i c\u00f9ng s\u1ee5p \u0111\u1ed5,`,
  `n\u1ed5 th\u00e0nh si\u00eau t\u00e2n tinh,`,
  `c\u00e1c nguy\u00ean t\u1ed1 n\u00e0y ph\u00e2n t\u00e1n kh\u1eafp v\u0169 tr\u1ee5,`,
  `v\u00e0 t\u1ed5ng h\u1ee3p v\u1eadt ch\u1ea5t m\u1edbi,`,
  `gi\u1ed1ng nh\u01b0 ph\u00e2n t\u1eed n\u01b0\u1edbc m\u00e0 ch\u00fang ta bi\u1ebft.`,
  `C\u00e1c ph\u00e2n t\u1eed n\u01b0\u1edbc n\u00e0y t\u1ed3n t\u1ea1i trong c\u00e1c \u0111\u00e1m m\u00e2y b\u1ee5i,`,
  `c\u00e1c \u0111\u00e1m m\u00e2y b\u1ee5i \u0111\u00e3 h\u00ecnh th\u00e0nh h\u1ec7 m\u1eb7t tr\u1eddi c\u1ee7a ch\u00fang ta,`,
  `v\u00e0 sau khi h\u00ecnh th\u00e0nh, ch\u00fang va ch\u1ea1m nhi\u1ec1u h\u01a1n v\u1edbi h\u00e0nh tinh c\u1ee7a ch\u00fang ta.`,
  `Nh\u01b0ng c\u00f3 m\u1ed9t c\u00e2u h\u1ecfi l\u1edbn \u1edf \u0111\u00e2y m\u00e0 ch\u00fang ta ch\u01b0a c\u00f3 c\u00e2u tr\u1ea3 l\u1eddi:`,
  `C\u00f3 bao nhi\u00eau n\u01b0\u1edbc \u0111\u00e3 \u0111\u1ebfn Tr\u00e1i \u0110\u1ea5t,`,
  `v\u00e0 khi n\u00e0o th\u00ec \u0111\u1ebfn Tr\u00e1i \u0110\u1ea5t?`,
  `Theo m\u1ed9t gi\u1ea3 thuy\u1ebft,`,
  `khi \u0111\u00e1 h\u00ecnh th\u00e0nh,`,
  `m\u1ed9t l\u01b0\u1ee3ng n\u01b0\u1edbc t\u01b0\u01a1ng \u0111\u1ed1i nh\u1ecf \u0111\u00e3 \u0111\u1ebfn Tr\u00e1i \u0110\u1ea5t,`,
  `nhi\u1ec7t \u0111\u1ed9 cao v\u00e0 thi\u1ebfu kh\u00ed quy\u1ec3n s\u1ebd khi\u1ebfn n\u01b0\u1edbc nhanh ch\u00f3ng bay h\u01a1i tr\u1edf l\u1ea1i kh\u00f4ng gian,`,
  `n\u01b0\u1edbc kh\u00f4ng th\u1ec3 \u0111\u01b0\u1ee3c gi\u1eef l\u1ea1i tr\u00ean Tr\u00e1i \u0110\u1ea5t.`,
  `Cho \u0111\u1ebfn h\u00e0ng tri\u1ec7u n\u0103m sau,`,
  `khi b\u1ea7u kh\u00ed quy\u1ec3n \u0111\u1ea7u ti\u00ean c\u1ee7a ch\u00fang ta h\u00ecnh th\u00e0nh th\u00f4ng qua qu\u00e1 tr\u00ecnh tho\u00e1t kh\u00ed,`,
  `qu\u00e1 tr\u00ecnh n\u00e0y x\u1ea3y ra khi \u0111\u00e1 tan ch\u1ea3y trong l\u00f5i Tr\u00e1i \u0110\u1ea5t,`,
  `gi\u1ea3i ph\u00f3ng kh\u00ed n\u00fai l\u1eeda l\u00ean b\u1ec1 m\u1eb7t Tr\u00e1i \u0110\u1ea5t,`,
  `t\u1ea1o ra m\u1ed9t l\u1edbp kh\u00ed quy\u1ec3n c\u00f3 th\u1ec3 gi\u1eef l\u1ea1i c\u00e1c ph\u00e2n t\u1eed n\u01b0\u1edbc tho\u00e1t ra.`,
  `V\u1eady n\u01b0\u1edbc \u0111\u00e3 quay tr\u1edf l\u1ea1i Tr\u00e1i \u0110\u1ea5t b\u1eb1ng c\u00e1ch n\u00e0o?`,
  `C\u00e1c nh\u00e0 khoa h\u1ecdc t\u1eeb l\u00e2u \u0111\u00e3 nghi ng\u1edd r\u1eb1ng ph\u1ea7n l\u1edbn n\u01b0\u1edbc \u0111\u1ebfn t\u1eeb c\u00e1c sao ch\u1ed5i c\u00f3 b\u0103ng,`,
  `ho\u1eb7c c\u00f3 th\u1ec3 h\u01a1n l\u00e0 t\u1eeb c\u00e1c ti\u1ec3u h\u00e0nh tinh va v\u00e0o Tr\u00e1i \u0110\u1ea5t trong h\u00e0ng tri\u1ec7u n\u0103m.`,
  `Nghi\u00ean c\u1ee9u g\u1ea7n \u0111\u00e2y \u0111\u00e3 th\u00e1ch th\u1ee9c l\u00fd thuy\u1ebft n\u00e0y,`,
  `D\u1ef1a tr\u00ean ph\u00e2n t\u00edch thi\u00ean th\u1ea1ch chondrite cacbon h\u00ecnh th\u00e0nh ngay sau khi h\u1ec7 m\u1eb7t tr\u1eddi ra \u0111\u1eddi,`,
  `c\u00e1c nh\u00e0 khoa h\u1ecdc \u0111\u00e3 ph\u00e1t hi\u1ec7n ra r\u1eb1ng nh\u1eefng thi\u00ean th\u1ea1ch n\u00e0y kh\u00f4ng ch\u1ec9 ch\u1ee9a n\u01b0\u1edbc,`,
  `m\u00e0 th\u00e0nh ph\u1ea7n h\u00f3a h\u1ecdc kho\u00e1ng v\u1eadt c\u1ee7a ch\u00fang c\u00f2n ph\u00f9 h\u1ee3p v\u1edbi \u0111\u00e1 Tr\u00e1i \u0110\u1ea5t v\u00e0 c\u00e1c m\u1eabu v\u1eadt t\u1eeb ti\u1ec3u h\u00e0nh tinh h\u00ecnh th\u00e0nh c\u00f9ng th\u1eddi v\u1edbi Tr\u00e1i \u0110\u1ea5t.`,
  `Ph\u00e1t hi\u1ec7n n\u00e0y cho th\u1ea5y Tr\u00e1i \u0110\u1ea5t c\u00f3 th\u1ec3 \u0111\u00e3 t\u00edch l\u0169y m\u1ed9t l\u01b0\u1ee3ng l\u1edbn n\u01b0\u1edbc c\u00f3 th\u1ec3 gi\u1eef l\u1ea1i ngay t\u1eeb ban \u0111\u1ea7u.`,
  `M\u1eb7c d\u00f9 trong \u0111i\u1ec1u ki\u1ec7n thi\u1ebfu b\u1ea7u kh\u00ed quy\u1ec3n,`,
  `m\u1eb7c d\u00f9 c\u00e1c ti\u1ec3u h\u00e0nh tinh c\u00f3 th\u1ec3 mang th\u00eam n\u01b0\u1edbc theo th\u1eddi gian,`,
  `n\u1ebfu \u0111i\u1ec1u n\u00e0y l\u00e0 \u0111\u00fang,`,
  `s\u1ef1 s\u1ed1ng c\u00f3 th\u1ec3 \u0111\u00e3 h\u00ecnh th\u00e0nh s\u1edbm h\u01a1n nhi\u1ec1u so v\u1edbi suy ngh\u0129 tr\u01b0\u1edbc \u0111\u00e2y.`,
  `V\u00ec v\u1eady, ch\u00fang ta kh\u00f4ng bi\u1ebft ch\u1eafc ch\u1eafn li\u1ec7u n\u01b0\u1edbc tr\u00ean Tr\u00e1i \u0110\u1ea5t c\u00f3 \u0111\u1ebfn t\u1eeb d\u1ea1ng ban \u0111\u1ea7u c\u1ee7a n\u00f3 hay kh\u00f4ng,`,
  `hay t\u1eeb nh\u1eefng t\u00e1c \u0111\u1ed9ng sau n\u00e0y,`,
  `hay c\u1ea3 hai.`,
  `D\u00f9 th\u1ebf n\u00e0o \u0111i n\u1eefa, n\u01b0\u1edbc d\u00f9ng \u0111\u1ec3 t\u1eafm,`,
  `n\u01b0\u1edbc u\u1ed1ng v\u00e0 n\u01b0\u1edbc m\u00e1y,`,
  `kh\u00f4ng tr\u1ef1c ti\u1ebfp t\u1eeb c\u00e1c s\u00f4ng h\u1ed3 l\u00e2n c\u1eadn,`,
  `m\u00e0 l\u00e0 tr\u1ea3i qua m\u1ed9t cu\u1ed9c h\u1ed7n lo\u1ea1n,`,
  `m\u1ed9t cu\u1ed9c h\u00e0nh tr\u00ecnh d\u00e0i c\u1ee7a v\u0169 tr\u1ee5,`,
  `\u0111\u1ec3 \u0111\u1ebfn \u0111\u00e2y. B\u1ea3o v\u1ec7 v\u00e0 g\u00ecn gi\u1eef thi\u00ean nhi\u00ean c\u1ee7a ch\u00fang ta c\u1ea7n tr\u1edf th\u00e0nh \u01b0u ti\u00ean h\u00e0ng \u0111\u1ea7u c\u1ee7a m\u1ecdi qu\u1ed1c gia,`,
  `c\u00f4ng ty v\u00e0 c\u1ed9ng \u0111\u1ed3ng tr\u00ean th\u1ebf gi\u1edbi.`,
  `N\u1ebfu b\u1ea1n mu\u1ed1n bi\u1ebft nh\u1eefng b\u01b0\u1edbc c\u1ee5 th\u1ec3 m\u00e0 b\u1ea1n c\u00f3 th\u1ec3 th\u1ef1c hi\u1ec7n ngay b\u00e2y gi\u1edd \u0111\u1ec3 gi\u00fap \u0111\u1ea1t \u0111\u01b0\u1ee3c m\u1ee5c ti\u00eau n\u00e0y,`,
  `vui l\u00f2ng truy c\u1eadp edoted.com earthgoo.`,
];

