const TEDED_FOOD_EXPIRATION_EER4H6CYKC_TRANSLATIONS = [
  `B\u1ea1n \u0111\u00e3 v\u1ee9t b\u1ecf bao nhi\u00eau th\u1ef1c ph\u1ea9m trong t\u1ee7 l\u1ea1nh tr\u01b0\u1edbc khi ch\u00fang \u0111\u01b0\u1ee3c s\u1eed d\u1ee5ng?`,
  `B\u00e1nh m\u00ec k\u1eb9p th\u1ecbt c\u00f2n s\u00f3t l\u1ea1i t\u1eeb bu\u1ed5i d\u00e3 ngo\u1ea1i h\u00e8 n\u0103m ngo\u00e1i,`,
  `S\u1eefa \u0111\u00e3 h\u1ebft h\u1ea1n s\u1eed d\u1ee5ng,`,
  `C\u00e0 r\u1ed1t b\u1ecb m\u1ec1m?`,
  `C\u00e1c qu\u1ed1c gia tr\u00ean th\u1ebf gi\u1edbi l\u00e3ng ph\u00ed m\u1ed9t l\u01b0\u1ee3ng l\u1edbn th\u1ef1c ph\u1ea9m m\u1ed7i n\u0103m,`,
  `v\u00e0 Hoa K\u1ef3 l\u00e0 m\u1ed9t trong nh\u1eefng khu v\u1ef1c l\u00e3ng ph\u00ed nhi\u1ec1u nh\u1ea5t.`,
  `37% l\u01b0\u1ee3ng th\u1ef1c ph\u1ea9m l\u00e3ng ph\u00ed \u1edf M\u1ef9 \u0111\u1ebfn t\u1eeb c\u00e1c h\u1ed9 gia \u0111\u00ecnh \u0111\u01a1n l\u1ebb,`,
  `trong \u0111\u00f3 kho\u1ea3ng 20% th\u1ef1c ph\u1ea9m b\u1ecb v\u1ee9t b\u1ecf v\u00ec ng\u01b0\u1eddi ti\u00eau d\u00f9ng kh\u00f4ng ch\u1eafc ch\u1eafn v\u1ec1 c\u00e1ch hi\u1ec3u ng\u00e0y tr\u00ean nh\u00e3n,`,
  `nh\u01b0ng h\u1ea7u h\u1ebft th\u1ef1c ph\u1ea9m v\u1eabn an to\u00e0n \u0111\u1ec3 \u0103n.`,
  `N\u1ebfu ng\u00e0y th\u00e1ng tr\u00ean th\u1ef1c ph\u1ea9m kh\u00f4ng c\u00f3 ngh\u0129a l\u00e0 c\u00f3 th\u1ee9 g\u00ec \u0111\u00f3 b\u1ecb h\u1ecfng,`,
  `v\u1eady n\u00f3 c\u00f3 ngh\u0129a l\u00e0 g\u00ec?`,
  `Tr\u01b0\u1edbc th\u1ebf k\u1ef7 20,`,
  `n\u01a1i s\u1ea3n xu\u1ea5t th\u1ef1c ph\u1ea9m v\u00e0 n\u01a1i ti\u00eau th\u1ee5 c\u00f3 m\u1ed1i li\u00ean h\u1ec7 tr\u1ef1c ti\u1ebfp h\u01a1n.`,
  `Nhi\u1ec1u ng\u01b0\u1eddi bi\u1ebft c\u00e1ch \u0111\u00e1nh gi\u00e1 \u0111\u1ed9 t\u01b0\u01a1i b\u1eb1ng m\u1eaft th\u01b0\u1eddng,`,
  `m\u0169i v\u00e0 tay,`,
  `Nh\u01b0ng khi si\u00eau th\u1ecb b\u1eaft \u0111\u1ea7u nh\u1eadp th\u1ef1c ph\u1ea9m ch\u1ebf bi\u1ebfn,`,
  `th\u1eddi gian l\u01b0u tr\u1eef s\u1ea3n ph\u1ea9m s\u1ebd kh\u00f3 x\u00e1c \u0111\u1ecbnh h\u01a1n.`,
  `\u1ede M\u1ef9, nh\u00e2n vi\u00ean si\u00eau th\u1ecb theo d\u00f5i th\u1eddi gian th\u1ef1c ph\u1ea9m tr\u00ean k\u1ec7 d\u1ef1a tr\u00ean m\u00e3 bao b\u00ec.`,
  `V\u00e0o nh\u1eefng n\u0103m 1970, ng\u01b0\u1eddi ti\u00eau d\u00f9ng r\u1ea5t ph\u1ee5 thu\u1ed9c v\u00e0o lo\u1ea1i th\u00f4ng tin n\u00e0y.`,
  `Ng\u00e0y nay, nhi\u1ec1u si\u00eau th\u1ecb \u00e1p d\u1ee5ng quy t\u1eafc g\u1ecdi l\u00e0 th\u1eddi h\u1ea1n t\u01b0\u01a1i ngon,`,
  `nh\u00e0 s\u1ea3n xu\u1ea5t ho\u1eb7c nh\u00e0 b\u00e1n l\u1ebb s\u1ebd ghi ng\u00e0y t\u01b0\u01a1i ngon nh\u1ea5t l\u00ean s\u1ea3n ph\u1ea9m.`,
  `Ti\u00eau chu\u1ea9n m\u01a1 h\u1ed3 n\u00e0y kh\u00f4ng li\u00ean quan g\u00ec \u0111\u1ebfn ng\u00e0y h\u1ebft h\u1ea1n hay an to\u00e0n th\u1ef1c ph\u1ea9m,`,
  `th\u1ef1c ra n\u00f3 \u0111\u01b0\u1ee3c thi\u1ebft l\u1eadp m\u00e0 g\u1ea7n nh\u01b0 kh\u00f4ng c\u00f3 c\u01a1 s\u1edf khoa h\u1ecdc n\u00e0o,`,
  `c\u0169ng kh\u00f4ng c\u00f3 quy \u0111\u1ecbnh n\u00e0o v\u1ec1 vi\u1ec7c ghi nh\u1eefng ng\u00e0y n\u00e0o.`,
  `Nhi\u1ec1u nh\u00e0 s\u1ea3n xu\u1ea5t v\u00e0 nh\u00e0 b\u00e1n l\u1ebb c\u00f3 xu h\u01b0\u1edbng ghi ng\u00e0y n\u00e0y s\u1edbm h\u01a1n,`,
  `\u0111\u1ec3 \u0111\u1ea3m b\u1ea3o ng\u01b0\u1eddi ti\u00eau d\u00f9ng th\u01b0\u1edfng th\u1ee9c th\u1ef1c ph\u1ea9m t\u01b0\u01a1i ngon v\u00e0 quay l\u1ea1i mua h\u00e0ng th\u01b0\u1eddng xuy\u00ean.`,
  `\u0110i\u1ec1u n\u00e0y c\u00f3 ngh\u0129a l\u00e0 nhi\u1ec1u th\u1ef1c ph\u1ea9m v\u1eabn an to\u00e0n \u0111\u1ec3 \u0103n sau ng\u00e0y ghi tr\u00ean bao b\u00ec.`,
  `B\u00e1nh quy \u0111\u1ec3 l\u00e2u,`,
  `m\u00ec \u1ed1ng v\u00e0 c\u00e1c th\u1ef1c ph\u1ea9m kh\u00f4 kh\u00e1c c\u00f3 th\u1ec3 kh\u00f4ng c\u00f2n t\u01b0\u01a1i ngon,`,
  `nh\u01b0ng ch\u00fang kh\u00f4ng g\u00e2y ra r\u1ee7i ro s\u1ee9c kh\u1ecfe.`,
  `Th\u1ef1c ph\u1ea9m \u0111\u00f3ng h\u1ed9p c\u00f3 th\u1ec3 \u0111\u1ec3 \u0111\u01b0\u1ee3c v\u00e0i n\u0103m,`,
  `mi\u1ec5n l\u00e0 kh\u00f4ng c\u00f3 d\u1ea5u hi\u1ec7u ph\u1ed3ng h\u1ed9p ho\u1eb7c g\u1ec9 s\u00e9t.`,
  `Nhi\u1ec7t \u0111\u1ed9 th\u1ea5p trong t\u1ee7 l\u1ea1nh c\u00f3 th\u1ec3 \u1ee9c ch\u1ebf vi khu\u1ea9n g\u00e2y ng\u1ed9 \u0111\u1ed9c th\u1ef1c ph\u1ea9m,`,
  `b\u1ea3o qu\u1ea3n th\u1ef1c ph\u1ea9m \u0111\u00f4ng l\u1ea1nh \u0111\u00fang c\u00e1ch v\u00f4 th\u1eddi h\u1ea1n.`,
  `Tr\u1ee9ng \u0111\u1ec3 t\u1ee7 l\u1ea1nh c\u00f3 th\u1ec3 b\u1ea3o qu\u1ea3n t\u1edbi 5 tu\u1ea7n,`,
  `n\u1ebfu h\u1ecfng, b\u1ea1n s\u1ebd ng\u1eedi th\u1ea5y m\u00f9i.`,
  `B\u1ea1n c\u0169ng c\u00f3 th\u1ec3 ph\u00e1t hi\u1ec7n th\u1ef1c ph\u1ea9m h\u01b0 h\u1ecfng qua m\u00f9i l\u1ea1, b\u1ec1 m\u1eb7t d\u00ednh nh\u1edbt v\u00e0 n\u1ea5m m\u1ed1c.`,
  `B\u1ea1n c\u0169ng c\u00f3 th\u1ec3 ph\u00e1t hi\u1ec7n th\u1ef1c ph\u1ea9m h\u01b0 h\u1ecfng qua m\u00f9i l\u1ea1, b\u1ec1 m\u1eb7t d\u00ednh nh\u1edbt v\u00e0 n\u1ea5m m\u1ed1c.`,
  `T\u1ea5t nhi\u00ean, c\u00f3 nh\u1eefng tr\u01b0\u1eddng h\u1ee3p t\u1ed1t h\u01a1n l\u00e0 n\u00ean th\u1eadn tr\u1ecdng.`,
  `B\u1ed9 N\u00f4ng nghi\u1ec7p Hoa K\u1ef3 (USDA) khuy\u1ebfn ngh\u1ecb n\u00ean \u0103n ho\u1eb7c \u0111\u00f4ng l\u1ea1nh th\u1ecbt \u0111\u00e3 mua trong v\u00f2ng v\u00e0i ng\u00e0y.`,
  `Qu\u00e1 th\u1eddi h\u1ea1n ghi tr\u00ean nh\u00e3n,`,
  `salad \u0103n li\u1ec1n, th\u1ecbt ngu\u1ed9i v\u00e0 ph\u00f4 mai ch\u01b0a ti\u1ec7t tr\u00f9ng c\u00f3 kh\u1ea3 n\u0103ng ch\u1ee9a vi khu\u1ea9n g\u00e2y b\u1ec7nh,`,
  `kh\u00f4ng th\u1ec3 ph\u00e1t hi\u1ec7n ch\u1ec9 b\u1eb1ng m\u00f9i ho\u1eb7c v\u1ecb.`,
  `Ng\u00e0y ghi tr\u00ean h\u1ed9p s\u1eefa c\u00f4ng th\u1ee9c d\u00e0nh cho tr\u1ebb s\u01a1 sinh \u0111\u01b0\u1ee3c qu\u1ea3n l\u00fd v\u00ec l\u00fd do an to\u00e0n,`,
  `m\u1eb7c d\u00f9 m\u1ed9t s\u1ed1 nh\u00e3n m\u00e1c c\u00f3 hi\u1ec7u qu\u1ea3,`,
  `H\u1ea7u h\u1ebft c\u00e1c nh\u00e3n m\u00e1c th\u00ec kh\u00f4ng.`,
  `Trong m\u1ed9t cu\u1ed9c kh\u1ea3o s\u00e1t h\u01a1n 1.000 ng\u01b0\u1eddi M\u1ef9 v\u00e0o n\u0103m 2019,`,
  `h\u01a1n 70% n\u00f3i r\u1eb1ng h\u1ecd s\u1eed d\u1ee5ng ng\u00e0y th\u00e1ng \u0111\u1ec3 x\u00e1c \u0111\u1ecbnh xem th\u1ef1c ph\u1ea9m c\u00f3 c\u00f2n \u0103n \u0111\u01b0\u1ee3c kh\u00f4ng,`,
  `v\u00e0 g\u1ea7n 60% ch\u1ec9 ra r\u1eb1ng h\u1ecd s\u1ebd v\u1ee9t b\u1ecf b\u1ea5t c\u1ee9 th\u1ee9 g\u00ec`,
  `ch\u1ec9 c\u1ea7n qu\u00e1 h\u1ea1n s\u1eed d\u1ee5ng.`,
  `C\u00e1c nh\u00e0 h\u00e0ng v\u00e0 si\u00eau th\u1ecb c\u0169ng th\u01b0\u1eddng l\u00e0m nh\u01b0 v\u1eady.`,
  `\u0110\u1ec3 tr\u00e1nh l\u00e3ng ph\u00ed nh\u01b0 v\u1eady,`,
  `nhi\u1ec1u chuy\u00ean gia k\u00eau g\u1ecdi ban h\u00e0nh lu\u1eadt,`,
  `y\u00eau c\u1ea7u s\u1eed d\u1ee5ng hai lo\u1ea1i nh\u00e3n ng\u00e0y th\u00e1ng sau:`,
  `Ng\u00e0y \u201cs\u1eed d\u1ee5ng t\u1ed1t nh\u1ea5t\u201d cho \u0111\u1ed9 t\u01b0\u01a1i ngon,`,
  `v\u00e0 ng\u00e0y \u201ch\u1ea1n s\u1eed d\u1ee5ng\u201d cho \u0111\u1ed9 an to\u00e0n.`,
  `Gi\u1ea3i ph\u00e1p n\u00e0y kh\u00f4ng ho\u00e0n h\u1ea3o, nh\u01b0ng m\u1ed9t s\u1ed1 nh\u00e0 nghi\u00ean c\u1ee9u M\u1ef9 \u01b0\u1edbc t\u00ednh r\u1eb1ng vi\u1ec7c \u00e1p d\u1ee5ng c\u00e1c quy \u0111\u1ecbnh n\u00e0y \u1edf c\u1ea5p qu\u1ed1c gia`,
  `c\u00f3 th\u1ec3 tr\u00e1nh \u0111\u01b0\u1ee3c kho\u1ea3ng 398.000 t\u1ea5n th\u1ef1c ph\u1ea9m b\u1ecb l\u00e3ng ph\u00ed m\u1ed7i n\u0103m.`,
  `C\u00e1c si\u00eau th\u1ecb c\u0169ng c\u00f3 th\u1ec3 lo\u1ea1i b\u1ecf nh\u00e3n ng\u00e0y th\u00e1ng tr\u00ean s\u1ea3n ph\u1ea9m,`,
  `nh\u01b0 m\u1ed9t s\u1ed1 chu\u1ed7i si\u00eau th\u1ecb c\u1ee7a Anh \u0111\u00e3 l\u00e0m,`,
  `khuy\u1ebfn kh\u00edch ng\u01b0\u1eddi ti\u00eau d\u00f9ng t\u1ef1 m\u00ecnh \u0111\u00e1nh gi\u00e1.`,
  `Nhi\u1ec1u chuy\u00ean gia k\u00eau g\u1ecdi ban h\u00e0nh ch\u00ednh s\u00e1ch,`,
  `khuy\u1ebfn kh\u00edch c\u00e1c si\u00eau th\u1ecb v\u00e0 nh\u00e0 h\u00e0ng t\u1eb7ng th\u1ef1c ph\u1ea9m ch\u01b0a b\u00e1n h\u1ebft.`,
  `Ng\u00e0y nay, s\u1ef1 hi\u1ec3u l\u1ea7m v\u1ec1 ng\u00e0y h\u1ebft h\u1ea1n \u0111\u00e3 khi\u1ebfn \u00edt nh\u1ea5t 20 bang \u1edf M\u1ef9 h\u1ea1n ch\u1ebf vi\u1ec7c t\u1eb7ng th\u1ef1c ph\u1ea9m qu\u00e1 h\u1ea1n ghi tr\u00ean nh\u00e3n.`,
  `M\u1eb7c d\u00f9 ch\u00ednh ph\u1ee7 li\u00ean bang th\u1ef1c s\u1ef1 khuy\u1ebfn kh\u00edch vi\u1ec7c t\u1eb7ng th\u1ef1c ph\u1ea9m nh\u01b0 v\u1eady,`,
  `nh\u1eefng qu\u1ed1c gia nh\u01b0 Ph\u00e1p c\u00f2n \u0111i xa h\u01a1n,`,
  `y\u00eau c\u1ea7u nhi\u1ec1u si\u00eau th\u1ecb ph\u1ea3i t\u1eb7ng th\u1ef1c ph\u1ea9m ch\u01b0a b\u00e1n h\u1ebft.`,
  `Cho d\u00f9 ch\u00ednh ph\u1ee7 c\u1ee7a b\u1ea1n ch\u1ecdn c\u00e1ch n\u00e0o \u0111i n\u1eefa,`,
  `c\u00e1ch t\u1ed1t nh\u1ea5t \u0111\u1ec3 tr\u00e1nh l\u00e3ng ph\u00ed th\u1ef1c ph\u1ea9m l\u00e0 mua bao nhi\u00eau \u0103n b\u1ea5y nhi\u00eau.`,
  `\u0110\u1eebng qu\u00ean, m\u1eaft c\u1ee7a b\u1ea1n,`,
  `m\u0169i v\u00e0 l\u01b0\u1ee1i th\u01b0\u1eddng \u0111\u1ee7 \u0111\u1ec3 \u0111\u00e1nh gi\u00e1 xem th\u1ef1c ph\u1ea9m \u0111\u00f3 n\u00ean v\u00e0o b\u1ee5ng b\u1ea1n hay v\u00e0o th\u00f9ng r\u00e1c.`,
  `Ch\u00fang ta c\u00f3 c\u00f4ng c\u1ee5 v\u00e0 ki\u1ebfn th\u1ee9c \u0111\u1ec3 c\u1ee9u th\u1ebf gi\u1edbi,`,
  `nh\u01b0ng b\u01b0\u1edbc ti\u1ebfp theo l\u00e0 g\u00ec?`,
  `H\u00e3y truy c\u1eadp edted.com/earthgoo \u0111\u1ec3 t\u00ecm hi\u1ec3u l\u1ed9 tr\u00ecnh b\u1ea1n c\u00f3 th\u1ec3 theo d\u00f5i,`,
  `v\u00e0 nh\u1eefng h\u00e0nh \u0111\u1ed9ng c\u1ee5 th\u1ec3 b\u1ea1n c\u00f3 th\u1ec3 th\u1ef1c hi\u1ec7n,`,
  `\u0111\u1ec3 t\u1ea1o ra s\u1ef1 thay \u0111\u1ed5i.`,
];

