const TEDED_LIANGZHU_LEGEND_YNTEL_JSFDY_TRANSLATIONS = [
  `Ch\u00fac Anh \u0110\u00e0i thay trang ph\u1ee5c,`,
  `chu\u1ea9n b\u1ecb t\u1eeb bi\u1ec7t cha m\u1eb9.`,
  `\u1ede nh\u00e0, n\u00e0ng lu\u00f4n l\u00e0 m\u1ed9t ng\u01b0\u1eddi con g\u00e1i ngoan ngo\u00e3n,`,
  `n\u00e0ng tinh th\u00f4ng th\u00eau th\u00f9a,`,
  `khi\u1ebfn cha m\u1eb9 t\u1ef1 h\u00e0o v\u1ec1 t\u00e0i n\u0103ng c\u1ee7a n\u00e0ng.`,
  `M\u1eb7c d\u00f9 v\u1eady, \u0111i\u1ec1u Anh \u0110\u00e0i th\u1ef1c s\u1ef1 mu\u1ed1n l\u00e0m l\u00e0 \u0111\u01b0\u1ee3c \u0111i h\u1ecdc.`,
  `D\u00f9 h\u1ecdc vi\u1ec7n Kh\u1ed5ng T\u1eed \u1edf H\u00e0ng Ch\u00e2u ch\u1ec9 nh\u1eadn nam sinh,`,
  `n\u00e0ng \u0111\u00e3 c\u1ea7u xin cha m\u1eb9 cho ph\u00e9p m\u00ecnh gi\u1ea3 trai \u0111i h\u1ecdc.`,
  `Cha m\u1eb9 th\u1ea5y n\u00e0ng \u00fd ch\u00ed ki\u00ean quy\u1ebft,`,
  `l\u1ea1i th\u1ea5y gi\u1ea3 trang kh\u00f4ng l\u1ed9 s\u01a1 h\u1edf,`,
  `cu\u1ed1i c\u00f9ng \u0111\u00e0nh \u0111\u1ed3ng \u00fd.`,
  `Tuy nhi\u00ean, cha m\u1eb9 y\u00eau c\u1ea7u Anh \u0110\u00e0i ph\u1ea3i \u0111\u1ea3m b\u1ea3o gi\u1ea5u th\u00e2n ph\u1eadn,`,
  `v\u00e0 sau khi h\u1ecdc xong ph\u1ea3i v\u1ec1 nh\u00e0,`,
  `theo s\u1ef1 s\u1eafp \u0111\u1eb7t c\u1ee7a h\u1ecd m\u00e0 tr\u1edf l\u1ea1i cu\u1ed9c s\u1ed1ng truy\u1ec1n th\u1ed1ng c\u1ee7a ng\u01b0\u1eddi ph\u1ee5 n\u1eef.`,
  `Anh \u0110\u00e0i t\u1eeb \u0111\u00f3 vui v\u1ebb b\u1eaft \u0111\u1ea7u chuy\u1ebfn \u0111i H\u00e0ng Ch\u00e2u c\u1ee7a m\u00ecnh.`,
  `Tr\u00ean \u0111\u01b0\u1eddng \u0111i, n\u00e0ng l\u1ea1c \u1edf m\u1ed9t ng\u00e3 t\u01b0,`,
  `\u0110ang l\u00fac kh\u00f4ng bi\u1ebft \u0111i h\u01b0\u1edbng n\u00e0o,`,
  `m\u1ed9t ch\u00e0ng trai tr\u1ebb ti\u1ebfn \u0111\u1ebfn g\u1ea7n n\u00e0ng,`,
  `h\u1ecd c\u1ea3m th\u1ea5y r\u1ea5t t\u00e2m \u0111\u1ea7u \u00fd h\u1ee3p ngay t\u1eeb c\u00e1i nh\u00ecn \u0111\u1ea7u ti\u00ean.`,
  `Anh \u0110\u00e0i bi\u1ebft ch\u00e0ng trai t\u00ean l\u00e0 L\u01b0\u01a1ng S\u01a1n B\u00e1,`,
  `c\u0169ng mu\u1ed1n \u0111\u1ebfn h\u1ecdc \u1edf tr\u01b0\u1eddng Kh\u1ed5ng T\u1eed,`,
  `th\u1ebf l\u00e0 hai ng\u01b0\u1eddi c\u00f9ng \u0111i ti\u1ebfp,`,
  `t\u00e2m s\u1ef1 kh\u00f4ng ng\u1eebng. Anh \u0110\u00e0i nh\u1eadn ra d\u00f9 n\u00e0ng c\u1ea3i trang th\u00e0nh ng\u01b0\u1eddi kh\u00e1c,`,
  `nh\u01b0ng v\u1eabn c\u00f3 th\u1ec3 l\u00e0 ch\u00ednh m\u00ecnh m\u1ed9t c\u00e1ch tho\u1ea3i m\u00e1i tr\u01b0\u1edbc S\u01a1n B\u00e1.`,
  `\u0110\u1ec3 k\u1ef7 ni\u1ec7m t\u00ecnh b\u1ea1n l\u00e2u d\u00e0i v\u00e0 ch\u00e2n th\u00e0nh n\u00e0y,`,
  `hai ng\u01b0\u1eddi quy\u1ebft \u0111\u1ecbnh k\u1ebft ngh\u0129a huynh \u0111\u1ec7.`,
  `\u1ede tr\u01b0\u1eddng, Anh \u0110\u00e0i v\u00f9i \u0111\u1ea7u v\u00e0o s\u00e1ch v\u1edf,`,
  `c\u00f9ng S\u01a1n B\u00e1 h\u1ecdc h\u00e0nh v\u1ea5t v\u1ea3 \u0111\u1ebfn t\u1eadn \u0111\u00eam khuya.`,
  `Khi hai ng\u01b0\u1eddi \u1edf b\u00ean nhau,`,
  `h\u1ecd \u0111\u1ec1u c\u1ea3m th\u1ea5y an t\u00e2m v\u00e0 tho\u1ea3i m\u00e1i.`,
  `H\u1ecd s\u1ed1ng chung m\u1ed9t ph\u00f2ng,`,
  `M\u1eb7c d\u00f9 S\u01a1n B\u00e1 t\u1ecf ra nghi ng\u1edd,`,
  `nh\u01b0ng Anh \u0110\u00e0i v\u1eabn ki\u00ean quy\u1ebft t\u1ef1 m\u00ecnh \u0111i v\u1ec7 sinh v\u00e0 t\u1eafm r\u1eeda,`,
  `v\u00e0 d\u00f9 tr\u1eddi n\u1eafng n\u00f3ng \u0111\u1ebfn \u0111\u00e2u c\u0169ng c\u00e0i n\u00fat \u00e1o \u0111\u1ebfn t\u1eadn c\u1ed5.`,
  `\u0110\u00f4i khi Anh \u0110\u00e0i c\u0169ng nghe b\u1ea1n h\u1ecdc b\u00e0n t\u00e1n ri\u00eang v\u1ec1 h\u00e0nh vi k\u1ef3 l\u1ea1 c\u1ee7a c\u00f4.`,
  `Th\u1eddi gian tr\u00f4i nhanh, Anh \u0110\u00e0i h\u1ecdc h\u00e0nh ch\u0103m ch\u1ec9,`,
  `lu\u00f4n \u0111\u1ee9ng nh\u1ea5t l\u1edbp.`,
  `C\u00f4 c\u1ea3m th\u1ea5y kho\u1ea3ng c\u00e1ch gi\u1eefa nh\u1eefng ng\u00e0y \u0111\u00e3 qua v\u00e0 t\u01b0\u01a1ng lai mong \u0111\u1ee3i xa v\u1eddi nh\u01b0 c\u00e1ch bi\u1ec7t m\u1ed9t th\u1ebf gi\u1edbi.`,
  `Tuy nhi\u00ean, nh\u1eefng l\u1eddi \u0111\u1ed3n \u0111\u1ea1i c\u1ee9 th\u1ebf m\u00e0 lan truy\u1ec1n,`,
  `ng\u00e0y c\u00e0ng tr\u1edf n\u00ean tr\u1ea7m tr\u1ecdng h\u01a1n. Ba n\u0103m sau,`,
  `Anh \u0110\u00e0i bu\u1ed9c ph\u1ea3i r\u1eddi tr\u01b0\u1eddng h\u1ecdc,`,
  `c\u00f4 v\u00e0 S\u01a1n B\u00e1 chia tay trong n\u01b0\u1edbc m\u1eaft,`,
  `hy v\u1ecdng anh s\u1ebd c\u00f3 d\u1ecbp \u0111\u1ebfn th\u0103m c\u00f4.`,
  `Khi Anh \u0110\u00e0i tr\u1edf v\u1ec1 nh\u00e0,`,
  `cha m\u1eb9 c\u00f4 n\u00f3i r\u1eb1ng nh\u00e0 h\u1ecd M\u00e3 \u1edf l\u00e0ng b\u00ean \u0111\u00e3 c\u1eed ng\u01b0\u1eddi \u0111\u1ebfn h\u1ecfi c\u01b0\u1edbi,`,
  `H\u1ecd mong nh\u00e0 h\u1ecd Ch\u00fac g\u1ea3 con g\u00e1i cho con trai m\u00ecnh.`,
  `Cha m\u1eb9 c\u1ea3m th\u1ea5y hai nh\u00e0 m\u00f4n \u0111\u0103ng h\u1ed9 \u0111\u1ed1i,`,
  `n\u00ean \u0111\u00e3 \u0111\u1ed3ng \u00fd. Anh \u0110\u00e0i c\u1ed1 g\u1eafng che gi\u1ea5u n\u1ed7i th\u1ea5t v\u1ecdng trong l\u00f2ng,`,
  `t\u00f4n tr\u1ecdng v\u00e0 tu\u00e2n theo s\u1ef1 s\u1eafp \u0111\u1eb7t c\u1ee7a cha m\u1eb9.`,
  `N\u00e0ng v\u1eeba chu\u1ea9n b\u1ecb cho cu\u1ed9c s\u1ed1ng m\u1edbi,`,
  `v\u1eeba nh\u1edb v\u1ec1 S\u01a1n B\u00e1 n\u01a1i ph\u01b0\u01a1ng xa.`,
  `C\u00f9ng l\u00fac \u0111\u00f3, s\u1ef1 ra \u0111i c\u1ee7a Anh \u0110\u00e0i c\u0169ng khi\u1ebfn S\u01a1n B\u00e1 kh\u00f4ng c\u00f2n t\u00e2m tr\u00ed h\u1ecdc h\u00e0nh.`,
  `Khi cu\u1ed1i c\u00f9ng ch\u00e0ng \u0111\u1ebfn nh\u00e0 Anh \u0110\u00e0i,`,
  `ng\u01b0\u1eddi m\u1edf c\u1eeda l\u1ea1i l\u00e0 m\u1ed9t c\u00f4 g\u00e1i tr\u1ebb.`,
  `S\u01a1n B\u00e1 \u0111\u1ecbnh h\u1ecfi anh m\u00ecnh c\u00f3 \u1edf nh\u00e0 kh\u00f4ng,`,
  `nh\u01b0ng trong kho\u1ea3nh kh\u1eafc \u0111\u1ed1i m\u1eb7t,`,
  `ch\u00e0ng nh\u1eadn ra \u0111\u00e2y ch\u00ednh l\u00e0 ng\u01b0\u1eddi b\u1ea1n h\u1ecdc m\u00e0 m\u00ecnh y\u00eau qu\u00fd.`,
  `S\u01a1n B\u00e1 bi\u1ebft m\u00ecnh kh\u00f4ng th\u1ec3 ch\u1ecbu \u0111\u1ef1ng th\u00eam m\u1ed9t l\u1ea7n chia ly n\u00e0o n\u1eefa v\u1edbi Anh \u0110\u00e0i,`,
  `li\u1ec1n c\u1ea7u h\u00f4n n\u00e0ng,`,
  `nh\u01b0ng Anh \u0110\u00e0i \u0111au l\u00f2ng n\u00f3i v\u1edbi ch\u00e0ng r\u1eb1ng,`,
  `M\u00ecnh em \u0111\u00e3 c\u00f3 n\u01a1i c\u00f3 ch\u1ed1n r\u1ed3i.`,
  `S\u01a1n B\u00e1 \u0111au bu\u1ed3n nh\u01b0ng c\u0169ng hi\u1ec3u Anh \u0110\u00e0i kh\u00f4ng th\u1ec3 l\u00e0m tr\u00e1i \u00fd cha m\u1eb9.`,
  `H\u1ecd l\u1ea1i m\u1ed9t l\u1ea7n n\u1eefa chia ly.`,
  `S\u01a1n B\u00e1 v\u00ec th\u1ebf m\u00e0 \u0111\u1ed5 b\u1ec7nh, ng\u00e0y c\u00e0ng tr\u1ea7m tr\u1ecdng.`,
  `Gia \u0111\u00ecnh ch\u00e0ng lo l\u1eafng nh\u01b0 l\u1eeda \u0111\u1ed1t,`,
  `li\u1ec1n c\u1eed ng\u01b0\u1eddi mai m\u1ed1i \u0111\u1ebfn nh\u00e0 h\u1ecd Ch\u00fac c\u1ea7u h\u00f4n.`,
  `Nh\u01b0ng v\u00ec Anh \u0110\u00e0i \u0111\u00e3 c\u00f3 h\u00f4n \u01b0\u1edbc,`,
  `cha n\u00e0ng \u0111\u00e3 t\u1eeb ch\u1ed1i h\u00f4n s\u1ef1 n\u00e0y, v\u00ec n\u1ebfu h\u1ee7y h\u00f4n s\u1ebd l\u00e0m \u00f4 danh c\u1ea3 gia t\u1ed9c.`,
  `B\u1ec7nh t\u00ecnh c\u1ee7a S\u01a1n B\u00e1 v\u00ec th\u1ebf m\u00e0 chuy\u1ec3n bi\u1ebfn x\u1ea5u nhanh ch\u00f3ng,`,
  `ch\u00e0ng bi\u1ebft m\u00ecnh kh\u00f4ng th\u1ec3 s\u1ed1ng \u0111\u1ebfn ng\u00e0y Anh \u0110\u00e0i xu\u1ea5t gi\u00e1,`,
  `li\u1ec1n vi\u1ebft cho Anh \u0110\u00e0i m\u1ed9t phong th\u01b0 cu\u1ed1i c\u00f9ng.`,
  `Trong th\u01b0 n\u00f3i r\u1eb1ng, n\u1ebfu Anh \u0110\u00e0i y\u00eau ch\u00e0ng,`,
  `ch\u00e0ng hy v\u1ecdng tr\u00ean \u0111\u01b0\u1eddng n\u00e0ng v\u1ec1 nh\u00e0 ch\u1ed3ng,`,
  `h\u00e3y \u0111\u1ebfn th\u1eafp m\u1ed9t n\u00e9n h\u01b0\u01a1ng tr\u01b0\u1edbc m\u1ed9 ch\u00e0ng.`,
  `Ng\u00e0y xu\u1ea5t gi\u00e1,`,
  `Anh \u0110\u00e0i c\u1ea3m th\u1ea5y h\u00f4n l\u1ec5 nh\u01b0 m\u1ed9t \u0111\u00e1m tang.`,
  `Trong gi\u00f3 m\u01b0a v\u1ea7n v\u0169,`,
  `\u0111o\u00e0n xe ng\u1ef1a l\u01b0\u1ee3n l\u1edd qua th\u1ecb tr\u1ea5n,`,
  `Anh \u0110\u00e0i tho\u00e1t kh\u1ecfi \u0111o\u00e0n r\u01b0\u1edbc d\u00e2u,`,
  `qu\u1ef3 xu\u1ed1ng tr\u01b0\u1edbc m\u1ed9 S\u01a1n B\u00e1 th\u1eafp m\u1ed9t n\u00e9n h\u01b0\u01a1ng,`,
  `v\u00e0 kh\u00f3c l\u00f3c t\u1ebf b\u00e1i.`,
  `\u0110\u1ed9t nhi\u00ean, m\u1ed9t ti\u1ebfng s\u00e9t kinh ho\u00e0ng n\u1ed5 vang tr\u00ean kh\u00f4ng trung,`,
  `tia ch\u1edbp \u0111\u00e1nh v\u00e0o m\u1ed9 S\u01a1n B\u00e1, l\u00e0m v\u1ee1 bia \u0111\u00e1.`,
  `Anh \u0110\u00e0i kh\u00f4ng ch\u00fat do d\u1ef1 nh\u1ea3y xu\u1ed1ng m\u1ed9.`,
  `Khi cha m\u1eb9 n\u00e0ng v\u1ed9i v\u00e3 \u0111\u1ebfn c\u1ee9u con g\u00e1i,`,
  `hai con b\u01b0\u1edbm bay ra t\u1eeb khe \u0111\u00e1.`,
  `L\u1ea7n n\u00e0y, Anh \u0110\u00e0i h\u00f3a th\u00e2n v\u00ec t\u00ecnh y\u00eau,`,
  `cu\u1ed1i c\u00f9ng \u0111\u01b0\u1ee3c t\u1ef1 do. T\u1eeb \u0111\u00f3, n\u00e0ng v\u00e0 S\u01a1n B\u00e1 v\u0129nh vi\u1ec5n kh\u00f4ng xa r\u1eddi nhau, \u0111\u1eddi \u0111\u1eddi ki\u1ebfp ki\u1ebfp.`,
  `Nh\u1eefng c\u00e2u chuy\u1ec7n truy\u1ec1n l\u1ea1i t\u1eeb qu\u00e1 kh\u1ee9 gi\u00fap ch\u00fang ta hi\u1ec3u r\u00f5 h\u01a1n v\u1ec1 qu\u00e1 kh\u1ee9,`,
  `\u0111\u00f4i khi c\u00f2n gi\u00fap ch\u00fang ta hi\u1ec3u r\u00f5 h\u01a1n v\u1ec1 hi\u1ec7n t\u1ea1i.`,
  `\u0110\u0103ng k\u00fd k\u00eanh \u0111\u1ec3`,
  `kh\u00f4ng b\u1ecf l\u1ee1 b\u1ea5t k\u1ef3 truy\u1ec1n thuy\u1ebft th\u00fa v\u1ecb n\u00e0o.`,
];

